window.MGProseData("d0799a3e061fc7a6ebb1ae2309b6c02fb18c1ca40a6f420f2d2b9bed33b1ab76",{"html":"\u003cp>{}\u003c/p>\n\u003ch1>Fourier 逆、截断误差与参数边界\u003c/h1>\n\u003chr>\n\u003ch2>S1 有限频带上的逆\u003c/h2>\n\u003ch3>1. 算子在基底上的作用与可逆性\u003c/h3>\n\u003cp>在归一化环面 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi mathvariant=\"double-struck\">T\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>=\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmsup>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathbb T^2 = \\mathbb R^2 / \\mathbb Z^2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 上，标准 Fourier 基底为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>e\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmsup>\u003cmi>e\u003c/mi>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>i\u003c/mi>\u003cmi>k\u003c/mi>\u003cmo>⋅\u003c/mo>\u003cmi>y\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmspace width=\"2em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>∈\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">e_k(y) = e^{2\\pi i k \\cdot y} \\qquad (k = (k_1, k_2) \\in \\mathbb Z^2).\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n对 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>e\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">e_k\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 作用微分算子 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>N\u003c/mi>\u003cmi>α\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmi>α\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"normal\">∂\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"normal\">∂\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">N_\\alpha = \\alpha \\partial_1 + \\partial_2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 得：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>N\u003c/mi>\u003cmi>α\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi>e\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmi>α\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>i\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsub>\u003cmi>e\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>+\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>i\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsub>\u003cmi>e\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>i\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>α\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsub>\u003cmi>e\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">N_\\alpha e_k(y) = \\alpha (2\\pi i k_1) e_k(y) + (2\\pi i k_2) e_k(y) = 2\\pi i (\\alpha k_1 + k_2) e_k(y).\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n空间 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>H\u003c/mi>\u003cmi>N\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">H_N\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 定义为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>H\u003c/mi>\u003cmi>N\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">span\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi mathvariant=\"double-struck\">C\u003c/mi>\u003c/msub>\u003cmrow>\u003cmo fence=\"true\">{\u003c/mo>\u003cmsub>\u003cmi>e\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msub>\u003cmo>:\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo separator=\"true\">,\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmn>0\u003c/mn>\u003cmo>\u0026lt;\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>k\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmi>N\u003c/mi>\u003cmo fence=\"true\">}\u003c/mo>\u003c/mrow>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">H_N = \\operatorname{span}_{\\mathbb C}\\left\\{ e_k : k \\in \\mathbb Z^2,\\ 0 \u0026lt; |k| \\le N \\right\\}.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n因为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>α\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003cmo>∖\u003c/mo>\u003cmi mathvariant=\"double-struck\">Q\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\alpha \\in \\mathbb R \\setminus \\mathbb Q\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 是无理数，对任意非零整数向量 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>k\u003c/mi>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">k = (k_1, k_2) \\ne (0,0)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>：\u003c/p>\n\u003cul>\n\u003cli>若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">k_1 = 0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，则 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">k_2 \\ne 0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，故 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>α\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\alpha k_1 + k_2 = k_2 \\ne 0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>；\u003c/li>\n\u003cli>若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">k_1 \\ne 0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，由于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>α\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\alpha\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 为无理数，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">k_2/k_1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 为有理数，故 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>α\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>α\u003c/mi>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\alpha k_1 + k_2 = k_1 (\\alpha + k_2/k_1) \\ne 0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/li>\n\u003c/ul>\n\u003cp>从而特征值 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>λ\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>i\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>α\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\lambda_k = 2\\pi i (\\alpha k_1 + k_2) \\ne 0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 对所有满足 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>0\u003c/mn>\u003cmo>\u0026lt;\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>k\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmi>N\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">0 \u0026lt; |k| \\le N\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的频率 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>k\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">k\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 恒成立。由于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>H\u003c/mi>\u003cmi>N\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">H_N\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 为有限维复线性空间且各基底向量 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>e\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">e_k\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>N\u003c/mi>\u003cmi>α\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">N_\\alpha\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的互不相同非零特征值的特征向量，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>N\u003c/mi>\u003cmi>α\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">N_\\alpha\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>H\u003c/mi>\u003cmi>N\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">H_N\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 上的限制为双射。\u003c/p>\n\u003ch3>2. 逆算子构造\u003c/h3>\n\u003cp>对任意 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsub>\u003cmi>H\u003c/mi>\u003cmi>N\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">F \\in H_N\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmn>0\u003c/mn>\u003cmo>\u0026lt;\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>k\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmi>N\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmover accent=\"true\">\u003cmi>F\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsup>\u003cmi>e\u003c/mi>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>i\u003c/mi>\u003cmi>k\u003c/mi>\u003cmo>⋅\u003c/mo>\u003cmi>y\u003c/mi>\u003c/mrow>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">F(y) = \\sum_{0 \u0026lt; |k| \\le N} \\widehat{F}(k) e^{2\\pi i k \\cdot y}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，其在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>H\u003c/mi>\u003cmi>N\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">H_N\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 上的唯一逆象为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsubsup>\u003cmi>N\u003c/mi>\u003cmi>α\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msubsup>\u003cmi>F\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmunder>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmn>0\u003c/mn>\u003cmo>\u0026lt;\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>k\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmi>N\u003c/mi>\u003c/mrow>\u003c/munder>\u003cmfrac>\u003cmrow>\u003cmover accent=\"true\">\u003cmi>F\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>i\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>α\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/mfrac>\u003cmsup>\u003cmi>e\u003c/mi>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>i\u003c/mi>\u003cmi>k\u003c/mi>\u003cmo>⋅\u003c/mo>\u003cmi>y\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">N_\\alpha^{-1} F(y) = \\sum_{0 \u0026lt; |k| \\le N} \\frac{\\widehat{F}(k)}{2\\pi i (\\alpha k_1 + k_2)} e^{2\\pi i k \\cdot y}.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003ch3>3. \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>H\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msup>\u003cmo>→\u003c/mo>\u003cmsup>\u003cmi>H\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">H^r \\to H^r\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 逆范数精确式\u003c/h3>\n\u003cp>对于任意实数 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>r\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">r \\in \\mathbb R\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，空间 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>H\u003c/mi>\u003cmi>N\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">H_N\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 上的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>H\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">H^r\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 范数为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>F\u003c/mi>\u003cmsubsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>H\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msup>\u003cmn>2\u003c/mn>\u003c/msubsup>\u003cmo>=\u003c/mo>\u003cmunder>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmn>0\u003c/mn>\u003cmo>\u0026lt;\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>k\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmi>N\u003c/mi>\u003c/mrow>\u003c/munder>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>r\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmover accent=\"true\">\u003cmi>F\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>+\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmrow>\u003cmn>1\u003c/mn>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmn>2\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\|F\\|_{H^r}^2 = \\sum_{0 \u0026lt; |k| \\le N} \\langle k \\rangle^{2r} |\\widehat{F}(k)|^2, \\qquad \\langle k \\rangle = (1+|k|^2)^{1/2}.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n因此\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsubsup>\u003cmi>N\u003c/mi>\u003cmi>α\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msubsup>\u003cmi>F\u003c/mi>\u003cmsubsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>H\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msup>\u003cmn>2\u003c/mn>\u003c/msubsup>\u003cmo>=\u003c/mo>\u003cmunder>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmn>0\u003c/mn>\u003cmo>\u0026lt;\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>k\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmi>N\u003c/mi>\u003c/mrow>\u003c/munder>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>r\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmfrac>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmover accent=\"true\">\u003cmi>F\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003cmrow>\u003cmn>4\u003c/mn>\u003cmsup>\u003cmi>π\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>α\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmsup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003c/mfrac>\u003cmo>≤\u003c/mo>\u003cmsup>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmunder>\u003cmrow>\u003cmi>max\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmn>0\u003c/mn>\u003cmo>\u0026lt;\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>k\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmi>N\u003c/mi>\u003c/mrow>\u003c/munder>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>α\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003c/mfrac>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>F\u003c/mi>\u003cmsubsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>H\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msup>\u003cmn>2\u003c/mn>\u003c/msubsup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\|N_\\alpha^{-1} F\\|_{H^r}^2 = \\sum_{0 \u0026lt; |k| \\le N} \\langle k \\rangle^{2r} \\frac{|\\widehat{F}(k)|^2}{4\\pi^2 |\\alpha k_1 + k_2|^2} \\le \\left(\\max_{0 \u0026lt; |k| \\le N} \\frac{1}{2\\pi |\\alpha k_1 + k_2|}\\right)^2 \\|F\\|_{H^r}^2.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n由于有限集 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>:\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo>\u0026lt;\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>k\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmi>N\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\{k \\in \\mathbb Z^2 : 0 \u0026lt; |k| \\le N\\}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 上的最小值可以取到，记\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>k\u003c/mi>\u003cmo>∗\u003c/mo>\u003c/msup>\u003cmo>∈\u003c/mo>\u003cmsub>\u003cmo>\u003cmi mathvariant=\"normal\">argmin\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mo>\u003cmrow>\u003cmn>0\u003c/mn>\u003cmo>\u0026lt;\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>k\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmi>N\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>α\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">k^* \\in \\mathop{\\operatorname{argmin}}_{0 \u0026lt; |k| \\le N} |\\alpha k_1 + k_2|.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n取测试函数 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>F\u003c/mi>\u003cmo>∗\u003c/mo>\u003c/msup>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmsup>\u003cmi>e\u003c/mi>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>i\u003c/mi>\u003cmsup>\u003cmi>k\u003c/mi>\u003cmo>∗\u003c/mo>\u003c/msup>\u003cmo>⋅\u003c/mo>\u003cmi>y\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmo>∈\u003c/mo>\u003cmsub>\u003cmi>H\u003c/mi>\u003cmi>N\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">F^*(y) = e^{2\\pi i k^* \\cdot y} \\in H_N\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，显然 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>F\u003c/mi>\u003cmo>∗\u003c/mo>\u003c/msup>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>H\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msup>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmsup>\u003cmi>k\u003c/mi>\u003cmo>∗\u003c/mo>\u003c/msup>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmi>r\u003c/mi>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\|F^*\\|_{H^r} = \\langle k^* \\rangle^r\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，且\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsubsup>\u003cmi>N\u003c/mi>\u003cmi>α\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msubsup>\u003cmsup>\u003cmi>F\u003c/mi>\u003cmo>∗\u003c/mo>\u003c/msup>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>H\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msup>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmrow>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmsup>\u003cmi>k\u003c/mi>\u003cmo>∗\u003c/mo>\u003c/msup>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmi>r\u003c/mi>\u003c/msup>\u003c/mrow>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>α\u003c/mi>\u003cmsubsup>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003cmo>∗\u003c/mo>\u003c/msubsup>\u003cmo>+\u003c/mo>\u003cmsubsup>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003cmo>∗\u003c/mo>\u003c/msubsup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003c/mfrac>\u003cmo>=\u003c/mo>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmunder>\u003cmrow>\u003cmi>min\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmn>0\u003c/mn>\u003cmo>\u0026lt;\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>k\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmi>N\u003c/mi>\u003c/mrow>\u003c/munder>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>α\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003c/mfrac>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>F\u003c/mi>\u003cmo>∗\u003c/mo>\u003c/msup>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>H\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msup>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\|N_\\alpha^{-1} F^*\\|_{H^r} = \\frac{\\langle k^* \\rangle^r}{2\\pi |\\alpha k_1^* + k_2^*|} = \\left(\\frac{1}{2\\pi \\min_{0 \u0026lt; |k| \\le N} |\\alpha k_1 + k_2|}\\right) \\|F^*\\|_{H^r}.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n因此，对任意实数 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>r\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">r \\in \\mathbb R\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>H\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msup>\u003cmo>→\u003c/mo>\u003cmsup>\u003cmi>H\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">H^r \\to H^r\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的算子逆范数精确式为：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsubsup>\u003cmi>N\u003c/mi>\u003cmi>α\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msubsup>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmrow>\u003cmi mathvariant=\"script\">L\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmi>H\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msup>\u003cmo>∩\u003c/mo>\u003cmsub>\u003cmi>H\u003c/mi>\u003cmi>N\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsup>\u003cmi>H\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msup>\u003cmo>∩\u003c/mo>\u003cmsub>\u003cmi>H\u003c/mi>\u003cmi>N\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmunder>\u003cmrow>\u003cmi>min\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmn>0\u003c/mn>\u003cmo>\u0026lt;\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>k\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmi>N\u003c/mi>\u003c/mrow>\u003c/munder>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>α\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003c/mfrac>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\|N_\\alpha^{-1}\\|_{\\mathcal L(H^r \\cap H_N, H^r \\cap H_N)} = \\frac{1}{2\\pi \\min_{0 \u0026lt; |k| \\le N} |\\alpha k_1 + k_2|}.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003chr>\n\u003ch2>S2 有算术界的截断误差\u003c/h2>\n\u003ch3>1. 光滑解 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>u\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">u\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的构造与正则性验证\u003c/h3>\n\u003cp>给定 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsubsup>\u003cmi>C\u003c/mi>\u003cmn>0\u003c/mn>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/msubsup>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">T\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">F \\in C^\\infty_0(\\mathbb T^2)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，其均值为零：\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmover accent=\"true\">\u003cmi>F\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmo>∫\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">T\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/msub>\u003cmi>F\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\widehat{F}(0) = \\int_{\\mathbb T^2} F = 0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。由光滑性，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>F\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">F\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的 Fourier 系数急速衰减：对任意 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M \\ge 0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，存在常数 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>M\u003c/mi>\u003c/msub>\u003cmo>\u0026lt;\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A_M \u0026lt; \\infty\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 使得\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmover accent=\"true\">\u003cmi>F\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>M\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmspace width=\"2em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi mathvariant=\"normal\">∀\u003c/mi>\u003cmi>k\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|\\widehat{F}(k)| \\le A_M \\langle k \\rangle^{-M} \\qquad (\\forall k \\in \\mathbb Z^2).\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n形式定义\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>u\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmunder>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi>k\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>∖\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo stretchy=\"false\">}\u003c/mo>\u003c/mrow>\u003c/munder>\u003cmfrac>\u003cmrow>\u003cmover accent=\"true\">\u003cmi>F\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>i\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>α\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/mfrac>\u003cmsup>\u003cmi>e\u003c/mi>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>i\u003c/mi>\u003cmi>k\u003c/mi>\u003cmo>⋅\u003c/mo>\u003cmi>y\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">u(y) = \\sum_{k \\in \\mathbb Z^2 \\setminus \\{0\\}} \\frac{\\widehat{F}(k)}{2\\pi i (\\alpha k_1 + k_2)} e^{2\\pi i k \\cdot y}.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n已知算术下界条件：\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>α\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmi>c\u003c/mi>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmi>s\u003c/mi>\u003c/mrow>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|\\alpha k_1 + k_2| \\ge c \\langle k \\rangle^{-s}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>（\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>c\u003c/mi>\u003cmo>\u0026gt;\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>s\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">c \u0026gt; 0, s \\ge 0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>），故\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmover accent=\"true\">\u003cmi>u\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmover accent=\"true\">\u003cmi>F\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>α\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003c/mfrac>\u003cmo>≤\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>c\u003c/mi>\u003c/mrow>\u003c/mfrac>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmi>s\u003c/mi>\u003c/msup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmover accent=\"true\">\u003cmi>F\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|\\widehat{u}(k)| = \\frac{|\\widehat{F}(k)|}{2\\pi |\\alpha k_1 + k_2|} \\le \\frac{1}{2\\pi c} \\langle k \\rangle^s |\\widehat{F}(k)|.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n对任意多重指标 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>β\u003c/mi>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>β\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>β\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>∈\u003c/mo>\u003cmsubsup>\u003cmi mathvariant=\"double-struck\">N\u003c/mi>\u003cmn>0\u003c/mn>\u003cmn>2\u003c/mn>\u003c/msubsup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\beta = (\\beta_1, \\beta_2) \\in \\mathbb N_0^2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，取 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>β\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>s\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>3\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M = |\\beta| + s + 3\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，则\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmrow>\u003cmo fence=\"true\">∣\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"normal\">∂\u003c/mi>\u003cmi>β\u003c/mi>\u003c/msup>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmfrac>\u003cmrow>\u003cmover accent=\"true\">\u003cmi>F\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>i\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>α\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/mfrac>\u003cmsup>\u003cmi>e\u003c/mi>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>i\u003c/mi>\u003cmi>k\u003c/mi>\u003cmo>⋅\u003c/mo>\u003cmi>y\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cmo fence=\"true\">∣\u003c/mo>\u003c/mrow>\u003cmo>≤\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>β\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>β\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmover accent=\"true\">\u003cmi>u\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmfrac>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>β\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003c/mrow>\u003cmi>c\u003c/mi>\u003c/mfrac>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>β\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>s\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmover accent=\"true\">\u003cmi>F\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmfrac>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>β\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>M\u003c/mi>\u003c/msub>\u003c/mrow>\u003cmi>c\u003c/mi>\u003c/mfrac>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>3\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\left| \\partial^\\beta \\left( \\frac{\\widehat{F}(k)}{2\\pi i (\\alpha k_1 + k_2)} e^{2\\pi i k \\cdot y} \\right) \\right| \\le (2\\pi)^{|\\beta|} \\langle k \\rangle^{|\\beta|} |\\widehat{u}(k)| \\le \\frac{(2\\pi)^{|\\beta|-1}}{c} \\langle k \\rangle^{|\\beta|+s} |\\widehat{F}(k)| \\le \\frac{(2\\pi)^{|\\beta|-1} A_M}{c} \\langle k \\rangle^{-3}.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n由于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi>k\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>3\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmo>\u0026lt;\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\sum_{k \\in \\mathbb Z^2} \\langle k \\rangle^{-3} \u0026lt; \\infty\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，由 Weierstrass M 判别法，导数级数在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi mathvariant=\"double-struck\">T\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathbb T^2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 上绝对且一致收敛。因此 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>u\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsup>\u003cmi>C\u003c/mi>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/msup>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">T\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">u \\in C^\\infty(\\mathbb T^2)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。同时 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmover accent=\"true\">\u003cmi>u\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003cmtext>  \u003c/mtext>\u003cmo>⟹\u003c/mo>\u003cmtext>  \u003c/mtext>\u003cmsub>\u003cmo>∫\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">T\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/msub>\u003cmi>u\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\widehat{u}(0) = 0 \\implies \\int_{\\mathbb T^2} u = 0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，即 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>u\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsubsup>\u003cmi>C\u003c/mi>\u003cmn>0\u003c/mn>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/msubsup>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">T\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">u \\in C_0^\\infty(\\mathbb T^2)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。逐项微分立得 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>N\u003c/mi>\u003cmi>α\u003c/mi>\u003c/msub>\u003cmi>u\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>F\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">N_\\alpha u = F\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003ch3>2. 截断误差估计的证明\u003c/h3>\n\u003cp>频带截断解为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>N\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmunder>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmn>0\u003c/mn>\u003cmo>\u0026lt;\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>k\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmi>N\u003c/mi>\u003c/mrow>\u003c/munder>\u003cmfrac>\u003cmrow>\u003cmover accent=\"true\">\u003cmi>F\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>i\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>α\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/mfrac>\u003cmsup>\u003cmi>e\u003c/mi>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>i\u003c/mi>\u003cmi>k\u003c/mi>\u003cmo>⋅\u003c/mo>\u003cmi>y\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">u_N(y) = \\sum_{0 \u0026lt; |k| \\le N} \\frac{\\widehat{F}(k)}{2\\pi i (\\alpha k_1 + k_2)} e^{2\\pi i k \\cdot y}.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n两者的误差为高频尾项：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>u\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>N\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmunder>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>k\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>\u0026gt;\u003c/mo>\u003cmi>N\u003c/mi>\u003c/mrow>\u003c/munder>\u003cmfrac>\u003cmrow>\u003cmover accent=\"true\">\u003cmi>F\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>i\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>α\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/mfrac>\u003cmsup>\u003cmi>e\u003c/mi>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>i\u003c/mi>\u003cmi>k\u003c/mi>\u003cmo>⋅\u003c/mo>\u003cmi>y\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">u(y) - u_N(y) = \\sum_{|k| \u0026gt; N} \\frac{\\widehat{F}(k)}{2\\pi i (\\alpha k_1 + k_2)} e^{2\\pi i k \\cdot y}.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n计算其在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>H\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">H^r\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 范数下的值：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>u\u003c/mi>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>N\u003c/mi>\u003c/msub>\u003cmsubsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>H\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msup>\u003cmn>2\u003c/mn>\u003c/msubsup>\u003cmo>=\u003c/mo>\u003cmunder>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>k\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>\u0026gt;\u003c/mo>\u003cmi>N\u003c/mi>\u003c/mrow>\u003c/munder>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>r\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmfrac>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmover accent=\"true\">\u003cmi>F\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003cmrow>\u003cmn>4\u003c/mn>\u003cmsup>\u003cmi>π\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>α\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmsup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003c/mfrac>\u003cmo>≤\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmrow>\u003cmn>4\u003c/mn>\u003cmsup>\u003cmi>π\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmsup>\u003cmi>c\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003c/mfrac>\u003cmunder>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>k\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>\u0026gt;\u003c/mo>\u003cmi>N\u003c/mi>\u003c/mrow>\u003c/munder>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>r\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>s\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmover accent=\"true\">\u003cmi>F\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\|u - u_N\\|_{H^r}^2 = \\sum_{|k| \u0026gt; N} \\langle k \\rangle^{2r} \\frac{|\\widehat{F}(k)|^2}{4\\pi^2 |\\alpha k_1 + k_2|^2} \\le \\frac{1}{4\\pi^2 c^2} \\sum_{|k| \u0026gt; N} \\langle k \\rangle^{2r + 2s} |\\widehat{F}(k)|^2.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n对满足 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>k\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>\u0026gt;\u003c/mo>\u003cmi>N\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|k| \u0026gt; N\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的整频率 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>k\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">k\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，其 Euclidean 模长满足 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>≥\u003c/mo>\u003cmsup>\u003cmi>N\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|k|^2 \\ge N^2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>（由于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>k\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">k \\in \\mathbb Z^2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>N\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmi mathvariant=\"double-struck\">N\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">N \\in \\mathbb N\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 则 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>≥\u003c/mo>\u003cmsup>\u003cmi>N\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|k|^2 \\ge N^2 + 1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>；一般而言 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>k\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>\u0026gt;\u003c/mo>\u003cmi>N\u003c/mi>\u003cmtext>  \u003c/mtext>\u003cmo>⟹\u003c/mo>\u003cmtext>  \u003c/mtext>\u003cmn>1\u003c/mn>\u003cmo>+\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>≥\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>+\u003c/mo>\u003cmsup>\u003cmi>N\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|k| \u0026gt; N \\implies 1+|k|^2 \\ge 1+N^2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>），从而\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>+\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>≥\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>+\u003c/mo>\u003cmsup>\u003cmi>N\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\langle k \\rangle^2 = 1 + |k|^2 \\ge 1 + N^2.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n对于任意给定的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>q\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">q \\ge 0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，有\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>q\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmo>≤\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>+\u003c/mo>\u003cmsup>\u003cmi>N\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmi>q\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\langle k \\rangle^{-2q} \\le (1+N^2)^{-q}.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n将此不等式拆入权因子中：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>r\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>s\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>q\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>r\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>s\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>q\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmo>≤\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>+\u003c/mo>\u003cmsup>\u003cmi>N\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmi>q\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>r\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>s\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>q\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\langle k \\rangle^{2r + 2s} = \\langle k \\rangle^{-2q} \\langle k \\rangle^{2(r+s+q)} \\le (1+N^2)^{-q} \\langle k \\rangle^{2(r+s+q)}.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n代入求和式得到：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>u\u003c/mi>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>N\u003c/mi>\u003c/msub>\u003cmsubsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>H\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msup>\u003cmn>2\u003c/mn>\u003c/msubsup>\u003cmo>≤\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmrow>\u003cmn>4\u003c/mn>\u003cmsup>\u003cmi>π\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmsup>\u003cmi>c\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003c/mfrac>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>+\u003c/mo>\u003cmsup>\u003cmi>N\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmi>q\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmunder>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>k\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>\u0026gt;\u003c/mo>\u003cmi>N\u003c/mi>\u003c/mrow>\u003c/munder>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>r\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>s\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>q\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmover accent=\"true\">\u003cmi>F\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>≤\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>c\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>+\u003c/mo>\u003cmsup>\u003cmi>N\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmi>q\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>F\u003c/mi>\u003cmsubsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>H\u003c/mi>\u003cmrow>\u003cmi>r\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>s\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>q\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmn>2\u003c/mn>\u003c/msubsup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\|u - u_N\\|_{H^r}^2 \\le \\frac{1}{4\\pi^2 c^2} (1+N^2)^{-q} \\sum_{|k| \u0026gt; N} \\langle k \\rangle^{2(r+s+q)} |\\widehat{F}(k)|^2 \\le (2\\pi c)^{-2} (1+N^2)^{-q} \\|F\\|_{H^{r+s+q}}^2.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n开平方即得所证不等式：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>u\u003c/mi>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>N\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>H\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msup>\u003c/msub>\u003cmo>≤\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>c\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>+\u003c/mo>\u003cmsup>\u003cmi>N\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmi>q\u003c/mi>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmn>2\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>F\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>H\u003c/mi>\u003cmrow>\u003cmi>r\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>s\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>q\u003c/mi>\u003c/mrow>\u003c/msup>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\|u - u_N\\|_{H^r} \\le (2\\pi c)^{-1} (1 + N^2)^{-q/2} \\|F\\|_{H^{r+s+q}}.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003chr>\n\u003ch2>S3 固定频带内改变方向\u003c/h2>\n\u003ch3>1. 对应解的差项展开\u003c/h3>\n\u003cp>设 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsub>\u003cmi>H\u003c/mi>\u003cmi>N\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">F \\in H_N\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，其 Fourier 展开仅含 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>0\u003c/mn>\u003cmo>\u0026lt;\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>k\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmi>N\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">0 \u0026lt; |k| \\le N\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的项。由 S1，对应的解分别为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>α\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmunder>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmn>0\u003c/mn>\u003cmo>\u0026lt;\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>k\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmi>N\u003c/mi>\u003c/mrow>\u003c/munder>\u003cmfrac>\u003cmrow>\u003cmover accent=\"true\">\u003cmi>F\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>i\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>α\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/mfrac>\u003cmsup>\u003cmi>e\u003c/mi>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>i\u003c/mi>\u003cmi>k\u003c/mi>\u003cmo>⋅\u003c/mo>\u003cmi>y\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>β\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmunder>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmn>0\u003c/mn>\u003cmo>\u0026lt;\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>k\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmi>N\u003c/mi>\u003c/mrow>\u003c/munder>\u003cmfrac>\u003cmrow>\u003cmover accent=\"true\">\u003cmi>F\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>i\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>β\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/mfrac>\u003cmsup>\u003cmi>e\u003c/mi>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>i\u003c/mi>\u003cmi>k\u003c/mi>\u003cmo>⋅\u003c/mo>\u003cmi>y\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">u_\\alpha(y) = \\sum_{0 \u0026lt; |k| \\le N} \\frac{\\widehat{F}(k)}{2\\pi i (\\alpha k_1 + k_2)} e^{2\\pi i k \\cdot y}, \\qquad u_\\beta(y) = \\sum_{0 \u0026lt; |k| \\le N} \\frac{\\widehat{F}(k)}{2\\pi i (\\beta k_1 + k_2)} e^{2\\pi i k \\cdot y}.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n作差可得：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>α\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>β\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmunder>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmn>0\u003c/mn>\u003cmo>\u0026lt;\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>k\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmi>N\u003c/mi>\u003c/mrow>\u003c/munder>\u003cmfrac>\u003cmrow>\u003cmover accent=\"true\">\u003cmi>F\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>i\u003c/mi>\u003c/mrow>\u003c/mfrac>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmrow>\u003cmi>α\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003c/mrow>\u003c/mfrac>\u003cmo>−\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmrow>\u003cmi>β\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003c/mrow>\u003c/mfrac>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cmsup>\u003cmi>e\u003c/mi>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>i\u003c/mi>\u003cmi>k\u003c/mi>\u003cmo>⋅\u003c/mo>\u003cmi>y\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">u_\\alpha(y) - u_\\beta(y) = \\sum_{0 \u0026lt; |k| \\le N} \\frac{\\widehat{F}(k)}{2\\pi i} \\left( \\frac{1}{\\alpha k_1 + k_2} - \\frac{1}{\\beta k_1 + k_2} \\right) e^{2\\pi i k \\cdot y}.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n计算括号中的代数式：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmrow>\u003cmi>α\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003c/mrow>\u003c/mfrac>\u003cmo>−\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmrow>\u003cmi>β\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003c/mrow>\u003c/mfrac>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>β\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>−\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>α\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>α\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>β\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/mfrac>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>β\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>α\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003c/mrow>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>α\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>β\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/mfrac>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\frac{1}{\\alpha k_1 + k_2} - \\frac{1}{\\beta k_1 + k_2} = \\frac{(\\beta k_1 + k_2) - (\\alpha k_1 + k_2)}{(\\alpha k_1 + k_2)(\\beta k_1 + k_2)} = \\frac{(\\beta - \\alpha) k_1}{(\\alpha k_1 + k_2)(\\beta k_1 + k_2)}.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003ch3>2. 逐点频率与范数估计\u003c/h3>\n\u003cp>在频带 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>0\u003c/mn>\u003cmo>\u0026lt;\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>k\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmi>N\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">0 \u0026lt; |k| \\le N\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 内：\u003c/p>\n\u003col>\n\u003cli>分子中的整频率满足 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmsqrt>\u003cmrow>\u003cmsubsup>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003cmn>2\u003c/mn>\u003c/msubsup>\u003cmo>+\u003c/mo>\u003cmsubsup>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003cmn>2\u003c/mn>\u003c/msubsup>\u003c/mrow>\u003c/msqrt>\u003cmo>=\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>k\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmi>N\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|k_1| \\le \\sqrt{k_1^2 + k_2^2} = |k| \\le N\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>；\u003c/li>\n\u003cli>分母满足小除数下界假设：\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>α\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmi>δ\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|\\alpha k_1 + k_2| \\ge \\delta\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 且 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>β\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmi>δ\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|\\beta k_1 + k_2| \\ge \\delta\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/li>\n\u003c/ol>\n\u003cp>因此，乘子在每个模上的绝对值满足：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmrow>\u003cmo fence=\"true\">∣\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>i\u003c/mi>\u003c/mrow>\u003c/mfrac>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmrow>\u003cmi>α\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003c/mrow>\u003c/mfrac>\u003cmo>−\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmrow>\u003cmi>β\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003c/mrow>\u003c/mfrac>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cmo fence=\"true\">∣\u003c/mo>\u003c/mrow>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>α\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>β\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>α\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>β\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003c/mfrac>\u003cmo>≤\u003c/mo>\u003cmfrac>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>α\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>β\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>N\u003c/mi>\u003c/mrow>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmsup>\u003cmi>δ\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003c/mfrac>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\left| \\frac{1}{2\\pi i} \\left( \\frac{1}{\\alpha k_1 + k_2} - \\frac{1}{\\beta k_1 + k_2} \\right) \\right| = \\frac{|\\alpha - \\beta| |k_1|}{2\\pi |\\alpha k_1 + k_2| |\\beta k_1 + k_2|} \\le \\frac{|\\alpha - \\beta| N}{2\\pi \\delta^2}.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n代入 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>H\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">H^r\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 范数计算式：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable rowspacing=\"0.25em\" columnalign=\"right left\" columnspacing=\"0em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>α\u003c/mi>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>β\u003c/mi>\u003c/msub>\u003cmsubsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>H\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msup>\u003cmn>2\u003c/mn>\u003c/msubsup>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmrow>\u003c/mrow>\u003cmo>=\u003c/mo>\u003cmunder>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmn>0\u003c/mn>\u003cmo>\u0026lt;\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>k\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmi>N\u003c/mi>\u003c/mrow>\u003c/munder>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>r\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmsup>\u003cmrow>\u003cmo fence=\"true\">∣\u003c/mo>\u003cmfrac>\u003cmrow>\u003cmover accent=\"true\">\u003cmi>F\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>i\u003c/mi>\u003c/mrow>\u003c/mfrac>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmrow>\u003cmi>α\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003c/mrow>\u003c/mfrac>\u003cmo>−\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmrow>\u003cmi>β\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003c/mrow>\u003c/mfrac>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cmo fence=\"true\">∣\u003c/mo>\u003c/mrow>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmrow>\u003c/mrow>\u003cmo>≤\u003c/mo>\u003cmsup>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmfrac>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>α\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>β\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>N\u003c/mi>\u003c/mrow>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmsup>\u003cmi>δ\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003c/mfrac>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmunder>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmn>0\u003c/mn>\u003cmo>\u0026lt;\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>k\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmi>N\u003c/mi>\u003c/mrow>\u003c/munder>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>r\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmover accent=\"true\">\u003cmi>F\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>=\u003c/mo>\u003cmsup>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmfrac>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>α\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>β\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>N\u003c/mi>\u003c/mrow>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmsup>\u003cmi>δ\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003c/mfrac>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>F\u003c/mi>\u003cmsubsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>H\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msup>\u003cmn>2\u003c/mn>\u003c/msubsup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\\begin{aligned}\n\\|u_\\alpha - u_\\beta\\|_{H^r}^2 \u0026amp;= \\sum_{0 \u0026lt; |k| \\le N} \\langle k \\rangle^{2r} \\left| \\frac{\\widehat{F}(k)}{2\\pi i} \\left( \\frac{1}{\\alpha k_1 + k_2} - \\frac{1}{\\beta k_1 + k_2} \\right) \\right|^2 \\\\\n\u0026amp;\\le \\left( \\frac{|\\alpha - \\beta| N}{2\\pi \\delta^2} \\right)^2 \\sum_{0 \u0026lt; |k| \\le N} \\langle k \\rangle^{2r} |\\widehat{F}(k)|^2 = \\left( \\frac{|\\alpha - \\beta| N}{2\\pi \\delta^2} \\right)^2 \\|F\\|_{H^r}^2.\n\\end{aligned}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n两端开平方即证：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>α\u003c/mi>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>β\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>H\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msup>\u003c/msub>\u003cmo>≤\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>α\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>β\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>N\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmsup>\u003cmi>δ\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>F\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>H\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msup>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\|u_\\alpha - u_\\beta\\|_{H^r} \\le |\\alpha - \\beta| N (2\\pi \\delta^2)^{-1} \\|F\\|_{H^r}.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003chr>\n\u003ch2>S4 整体对象与全部恢复目标\u003c/h2>\n\u003ch3>1. 刻画可逆的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>α\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\alpha\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 类（光滑零均值解的存在唯一性）\u003c/h3>\n\u003cp>\u003cstrong>结论\u003c/strong>：\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>N\u003c/mi>\u003cmi>α\u003c/mi>\u003c/msub>\u003cmo>:\u003c/mo>\u003cmsubsup>\u003cmi>C\u003c/mi>\u003cmn>0\u003c/mn>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/msubsup>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">T\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>→\u003c/mo>\u003cmsubsup>\u003cmi>C\u003c/mi>\u003cmn>0\u003c/mn>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/msubsup>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">T\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">N_\\alpha: C_0^\\infty(\\mathbb T^2) \\to C_0^\\infty(\\mathbb T^2)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 为双射当且仅当 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>α\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\alpha\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 为 \u003cstrong>Diophantine 数\u003c/strong>（即非 Liouville 数，无理性测度 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>μ\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>α\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>\u0026lt;\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mu(\\alpha) \u0026lt; \\infty\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>）。等价地，存在常数 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>c\u003c/mi>\u003cmo>\u0026gt;\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>τ\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">c \u0026gt; 0, \\tau \\ge 1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 使得\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>α\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmi>c\u003c/mi>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmi>τ\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmspace width=\"2em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi mathvariant=\"normal\">∀\u003c/mi>\u003cmi>k\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>∖\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|\\alpha k_1 + k_2| \\ge c \\langle k \\rangle^{-\\tau} \\qquad (\\forall k \\in \\mathbb Z^2 \\setminus \\{0\\}).\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003cp>\u003cstrong>证明\u003c/strong>：\u003c/p>\n\u003cul>\n\u003cli>\u003cstrong>唯一性\u003c/strong>：对任意无理数 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>α\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\alpha\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>u\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsubsup>\u003cmi>C\u003c/mi>\u003cmn>0\u003c/mn>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/msubsup>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">T\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">u \\in C_0^\\infty(\\mathbb T^2)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 满足 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>N\u003c/mi>\u003cmi>α\u003c/mi>\u003c/msub>\u003cmi>u\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">N_\\alpha u = 0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，则其 Fourier 系数满足 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>i\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>α\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmover accent=\"true\">\u003cmi>u\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2\\pi i (\\alpha k_1 + k_2) \\widehat{u}(k) = 0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。由 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>α\u003c/mi>\u003cmo mathvariant=\"normal\">∉\u003c/mo>\u003cmi mathvariant=\"double-struck\">Q\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\alpha \\notin \\mathbb Q\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，当 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>k\u003c/mi>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">k \\ne 0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 时 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>α\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\alpha k_1 + k_2 \\ne 0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，故 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmover accent=\"true\">\u003cmi>u\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\widehat{u}(k) = 0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。又因 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>u\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">u\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 零均值，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmover accent=\"true\">\u003cmi>u\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\widehat{u}(0) = 0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。由 Fourier 级数惟一性，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>u\u003c/mi>\u003cmo>≡\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">u \\equiv 0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/li>\n\u003cli>\u003cstrong>充分性\u003c/strong>：若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>α\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\alpha\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 为 Diophantine 数，则对任意 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsubsup>\u003cmi>C\u003c/mi>\u003cmn>0\u003c/mn>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/msubsup>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">T\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">F \\in C_0^\\infty(\\mathbb T^2)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，形式解系数满足 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmover accent=\"true\">\u003cmi>u\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>c\u003c/mi>\u003c/mrow>\u003c/mfrac>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmi>τ\u003c/mi>\u003c/msup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmover accent=\"true\">\u003cmi>F\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|\\widehat{u}(k)| \\le \\frac{1}{2\\pi c} \\langle k \\rangle^\\tau |\\widehat{F}(k)|\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。由 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>F\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">F\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的光滑性，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmover accent=\"true\">\u003cmi>F\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|\\widehat{F}(k)|\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 衰减快于任意多项式反比，从而 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmover accent=\"true\">\u003cmi>u\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|\\widehat{u}(k)|\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 亦快于任意多项式反比衰减。由标准 Fourier 逆变换理论，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>u\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi>k\u003c/mi>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003c/msub>\u003cmover accent=\"true\">\u003cmi>u\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsup>\u003cmi>e\u003c/mi>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>i\u003c/mi>\u003cmi>k\u003c/mi>\u003cmo>⋅\u003c/mo>\u003cmi>y\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmo>∈\u003c/mo>\u003cmsubsup>\u003cmi>C\u003c/mi>\u003cmn>0\u003c/mn>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/msubsup>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">T\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">u(y) = \\sum_{k \\ne 0} \\widehat{u}(k) e^{2\\pi i k \\cdot y} \\in C_0^\\infty(\\mathbb T^2)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，且 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>N\u003c/mi>\u003cmi>α\u003c/mi>\u003c/msub>\u003cmi>u\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>F\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">N_\\alpha u = F\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/li>\n\u003cli>\u003cstrong>必要性\u003c/strong>：若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>α\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\alpha\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 不是 Diophantine 数（即为 Liouville 数），则对任意 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmi mathvariant=\"double-struck\">N\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M \\in \\mathbb N\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmrow>\u003cmi>inf\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmi>k\u003c/mi>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmi>M\u003c/mi>\u003c/msup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>α\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\inf_{k \\ne 0} \\langle k \\rangle^M |\\alpha k_1 + k_2| = 0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。由此可选出一列频率 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>k\u003c/mi>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>j\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmo>∈\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>∖\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo stretchy=\"false\">}\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">k^{(j)} \\in \\mathbb Z^2 \\setminus \\{0\\}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，满足 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmsup>\u003cmi>k\u003c/mi>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>j\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmo>\u0026gt;\u003c/mo>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmsup>\u003cmi>k\u003c/mi>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>j\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\langle k^{(j+1)} \\rangle \u0026gt; 2 \\langle k^{(j)} \\rangle\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 且\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>α\u003c/mi>\u003cmsubsup>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>j\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msubsup>\u003cmo>+\u003c/mo>\u003cmsubsup>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>j\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msubsup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmsup>\u003cmi>k\u003c/mi>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>j\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmi>j\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|\\alpha k_1^{(j)} + k_2^{(j)}| \\le \\langle k^{(j)} \\rangle^{-j}.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n构造 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmsubsup>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi>j\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/msubsup>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmsup>\u003cmi>k\u003c/mi>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>j\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmi>j\u003c/mi>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmn>2\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmsup>\u003cmi>e\u003c/mi>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>i\u003c/mi>\u003cmsup>\u003cmi>k\u003c/mi>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>j\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmo>⋅\u003c/mo>\u003cmi>y\u003c/mi>\u003c/mrow>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">F(y) = \\sum_{j=1}^\\infty \\langle k^{(j)} \\rangle^{-j/2} e^{2\\pi i k^{(j)} \\cdot y}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。对于任意固定 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>p\u003c/mi>\u003cmo>\u0026gt;\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">p \u0026gt; 0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，当 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>j\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>p\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">j \\ge 2p\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 时 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmsup>\u003cmi>k\u003c/mi>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>j\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmi>p\u003c/mi>\u003c/msup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmover accent=\"true\">\u003cmi>F\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmi>k\u003c/mi>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>j\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\langle k^{(j)} \\rangle^p |\\widehat{F}(k^{(j)})| \\le 1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，故 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsubsup>\u003cmi>C\u003c/mi>\u003cmn>0\u003c/mn>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/msubsup>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">T\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">F \\in C_0^\\infty(\\mathbb T^2)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。但形式解的 Fourier 系数满足\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmover accent=\"true\">\u003cmi>u\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmi>k\u003c/mi>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>j\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmrow>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmsup>\u003cmi>k\u003c/mi>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>j\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmi>j\u003c/mi>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmn>2\u003c/mn>\u003c/mrow>\u003c/msup>\u003c/mrow>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>α\u003c/mi>\u003cmsubsup>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>j\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msubsup>\u003cmo>+\u003c/mo>\u003cmsubsup>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>j\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msubsup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003c/mfrac>\u003cmo>≥\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003c/mrow>\u003c/mfrac>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmsup>\u003cmi>k\u003c/mi>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>j\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmrow>\u003cmi>j\u003c/mi>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmn>2\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmo>→\u003c/mo>\u003cmo>+\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>j\u003c/mi>\u003cmo>→\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|\\widehat{u}(k^{(j)})| = \\frac{\\langle k^{(j)} \\rangle^{-j/2}}{2\\pi |\\alpha k_1^{(j)} + k_2^{(j)}|} \\ge \\frac{1}{2\\pi} \\langle k^{(j)} \\rangle^{j/2} \\to +\\infty \\quad (j \\to \\infty).\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n由 Riemann-Lebesgue 引理，任何 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>C\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msup>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">T\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">C^0(\\mathbb T^2)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 函数（特别是光滑函数）的 Fourier 系数必须有界，矛盾！故此时不存在光滑解。\u003c/li>\n\u003c/ul>\n\u003ch3>2. 确定允许的损失指标集合 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>s\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo stretchy=\"false\">}\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\{s \\ge 0\\}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/h3>\n\u003cp>\u003cstrong>结论\u003c/strong>：对固定的无理数 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>α\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\alpha\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 及 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>s\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">s \\ge 0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，存在与 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>u\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">u\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 无关的有限常数 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>C\u003c/mi>\u003cmrow>\u003cmi>α\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>r\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>s\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">C_{\\alpha, r, s}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 使得\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>u\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>H\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msup>\u003c/msub>\u003cmo>≤\u003c/mo>\u003cmsub>\u003cmi>C\u003c/mi>\u003cmrow>\u003cmi>α\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>r\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>s\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsub>\u003cmi>N\u003c/mi>\u003cmi>α\u003c/mi>\u003c/msub>\u003cmi>u\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>H\u003c/mi>\u003cmrow>\u003cmi>r\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>s\u003c/mi>\u003c/mrow>\u003c/msup>\u003c/msub>\u003cmspace width=\"2em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi mathvariant=\"normal\">∀\u003c/mi>\u003cmi>u\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsubsup>\u003cmi>C\u003c/mi>\u003cmn>0\u003c/mn>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/msubsup>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">T\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\|u\\|_{H^r} \\le C_{\\alpha, r, s} \\|N_\\alpha u\\|_{H^{r+s}} \\qquad (\\forall u \\in C_0^\\infty(\\mathbb T^2))\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n当且仅当\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∃\u003c/mi>\u003cmi>c\u003c/mi>\u003cmo>\u0026gt;\u003c/mo>\u003cmn>0\u003c/mn>\u003cmspace width=\"1em\"/>\u003cmtext>使得\u003c/mtext>\u003cmspace width=\"1em\"/>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>α\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmi>c\u003c/mi>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmi>s\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmspace width=\"2em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi mathvariant=\"normal\">∀\u003c/mi>\u003cmi>k\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>∖\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\exists c \u0026gt; 0 \\quad \\text{使得} \\quad |\\alpha k_1 + k_2| \\ge c \\langle k \\rangle^{-s} \\qquad (\\forall k \\in \\mathbb Z^2 \\setminus \\{0\\}).\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n\u003cstrong>证明\u003c/strong>：\u003c/p>\n\u003cul>\n\u003cli>\u003cstrong>充分性\u003c/strong>：若上述算术下界成立，由 Parseval 定理：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>u\u003c/mi>\u003cmsubsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>H\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msup>\u003cmn>2\u003c/mn>\u003c/msubsup>\u003cmo>=\u003c/mo>\u003cmunder>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi>k\u003c/mi>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003c/munder>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>r\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmfrac>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmover accent=\"true\">\u003cmrow>\u003cmsub>\u003cmi>N\u003c/mi>\u003cmi>α\u003c/mi>\u003c/msub>\u003cmi>u\u003c/mi>\u003c/mrow>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003cmrow>\u003cmn>4\u003c/mn>\u003cmsup>\u003cmi>π\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>α\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmsup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003c/mfrac>\u003cmo>≤\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmrow>\u003cmn>4\u003c/mn>\u003cmsup>\u003cmi>π\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmsup>\u003cmi>c\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003c/mfrac>\u003cmunder>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi>k\u003c/mi>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003c/munder>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>r\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>s\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmover accent=\"true\">\u003cmrow>\u003cmsub>\u003cmi>N\u003c/mi>\u003cmi>α\u003c/mi>\u003c/msub>\u003cmi>u\u003c/mi>\u003c/mrow>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmrow>\u003cmn>4\u003c/mn>\u003cmsup>\u003cmi>π\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmsup>\u003cmi>c\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003c/mfrac>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsub>\u003cmi>N\u003c/mi>\u003cmi>α\u003c/mi>\u003c/msub>\u003cmi>u\u003c/mi>\u003cmsubsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>H\u003c/mi>\u003cmrow>\u003cmi>r\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>s\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmn>2\u003c/mn>\u003c/msubsup>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\|u\\|_{H^r}^2 = \\sum_{k \\ne 0} \\langle k \\rangle^{2r} \\frac{|\\widehat{N_\\alpha u}(k)|^2}{4\\pi^2 |\\alpha k_1 + k_2|^2} \\le \\frac{1}{4\\pi^2 c^2} \\sum_{k \\ne 0} \\langle k \\rangle^{2(r+s)} |\\widehat{N_\\alpha u}(k)|^2 = \\frac{1}{4\\pi^2 c^2} \\|N_\\alpha u\\|_{H^{r+s}}^2,\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n取 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>C\u003c/mi>\u003cmrow>\u003cmi>α\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>r\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>s\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>c\u003c/mi>\u003c/mrow>\u003c/mfrac>\u003cmo>\u0026lt;\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">C_{\\alpha, r, s} = \\frac{1}{2\\pi c} \u0026lt; \\infty\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 即可。\u003c/li>\n\u003cli>\u003cstrong>必要性\u003c/strong>：对每个单一频率 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>k\u003c/mi>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">k \\ne 0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，取 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmsup>\u003cmi>e\u003c/mi>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>i\u003c/mi>\u003cmi>k\u003c/mi>\u003cmo>⋅\u003c/mo>\u003cmi>y\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmo>∈\u003c/mo>\u003cmsubsup>\u003cmi>C\u003c/mi>\u003cmn>0\u003c/mn>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/msubsup>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">T\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">u_k(y) = e^{2\\pi i k \\cdot y} \\in C_0^\\infty(\\mathbb T^2)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。此时 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>H\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msup>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmi>r\u003c/mi>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\|u_k\\|_{H^r} = \\langle k \\rangle^r\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，且 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsub>\u003cmi>N\u003c/mi>\u003cmi>α\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>H\u003c/mi>\u003cmrow>\u003cmi>r\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>s\u003c/mi>\u003c/mrow>\u003c/msup>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>α\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmrow>\u003cmi>r\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>s\u003c/mi>\u003c/mrow>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\|N_\\alpha u_k\\|_{H^{r+s}} = 2\\pi |\\alpha k_1 + k_2| \\langle k \\rangle^{r+s}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。先验估计蕴含：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmi>r\u003c/mi>\u003c/msup>\u003cmo>≤\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmsub>\u003cmi>C\u003c/mi>\u003cmrow>\u003cmi>α\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>r\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>s\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>α\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmrow>\u003cmi>r\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>s\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmtext>  \u003c/mtext>\u003cmo>⟹\u003c/mo>\u003cmtext>  \u003c/mtext>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>α\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmsub>\u003cmi>C\u003c/mi>\u003cmrow>\u003cmi>α\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>r\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>s\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003c/mfrac>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmi>s\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\langle k \\rangle^r \\le 2\\pi C_{\\alpha, r, s} |\\alpha k_1 + k_2| \\langle k \\rangle^{r+s} \\implies |\\alpha k_1 + k_2| \\ge \\frac{1}{2\\pi C_{\\alpha, r, s}} \\langle k \\rangle^{-s}.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n注：由 Dirichlet 逼近定理，对任何无理数 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>α\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\alpha\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，必存在无穷多个 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>k\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">k\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 使得 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>α\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>\u0026lt;\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmsup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|\\alpha k_1 + k_2| \u0026lt; |k_1|^{-1}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，因此对任意无理数 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>α\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\alpha\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，合法的损失指标必有 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>s\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">s \\ge 1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。具体地：\u003c/li>\n\u003cli>若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>α\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\alpha\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的无理性测度为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>μ\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>α\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>\u0026lt;\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mu(\\alpha) \u0026lt; \\infty\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，则对所有 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>s\u003c/mi>\u003cmo>\u0026gt;\u003c/mo>\u003cmi>μ\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>α\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">s \u0026gt; \\mu(\\alpha) - 1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，该估计恒成立；对所有 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>s\u003c/mi>\u003cmo>\u0026lt;\u003c/mo>\u003cmi>μ\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>α\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">s \u0026lt; \\mu(\\alpha) - 1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，该估计不成立；在端点 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>s\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>μ\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>α\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">s = \\mu(\\alpha) - 1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，成立当且仅当 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">lim inf\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>k\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>→\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmrow>\u003cmi>μ\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>α\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>α\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>\u0026gt;\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\liminf_{|k| \\to \\infty} \\langle k \\rangle^{\\mu(\\alpha)-1} |\\alpha k_1 + k_2| \u0026gt; 0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/li>\n\u003cli>若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>α\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\alpha\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 为 Liouville 数，则合法的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>s\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">s\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 集合为空集 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∅\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\emptyset\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/li>\n\u003c/ul>\n\u003ch3>3. \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>α\u003c/mi>\u003cmo>∗\u003c/mo>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsqrt>\u003cmn>2\u003c/mn>\u003c/msqrt>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\alpha_* = \\sqrt{2} - 1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的最小损失 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>s\u003c/mi>\u003cmi>min\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">s_{\\min}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 及其可达性\u003c/h3>\n\u003cp>\u003cstrong>结论\u003c/strong>：最小损失为 \u003cstrong>\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>s\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">s = 1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/strong>，且 \u003cstrong>能够取到\u003c/strong>。\u003c/p>\n\u003cp>\u003cstrong>证明\u003c/strong>：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>α\u003c/mi>\u003cmo>∗\u003c/mo>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsqrt>\u003cmn>2\u003c/mn>\u003c/msqrt>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">[\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">;\u003c/mo>\u003cmn>2\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>2\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>2\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmo>…\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmo stretchy=\"false\">]\u003c/mo>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">[\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">;\u003c/mo>\u003cmover accent=\"true\">\u003cmn>2\u003c/mn>\u003cmo stretchy=\"true\">‾\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">]\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\alpha_* = \\sqrt{2} - 1 = [0; 2, 2, 2, \\dots] = [0; \\overline{2}]\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。其连分数展开的部分商全部为有限常数 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>a\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">a_n = 2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\n由连分数经典理论，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>α\u003c/mi>\u003cmo>∗\u003c/mo>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\alpha_*\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 属于坏逼近数（badly approximable number）。对所有 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>q\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>p\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">q \\ge 1, p \\in \\mathbb Z\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，有\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>q\u003c/mi>\u003cmsub>\u003cmi>α\u003c/mi>\u003cmo>∗\u003c/mo>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmi>p\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmrow>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmrow>\u003cmi>n\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003c/mrow>\u003c/mfrac>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>a\u003c/mi>\u003cmrow>\u003cmi>n\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmrow>\u003cmi>n\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003c/mfrac>\u003cmo>\u0026gt;\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmrow>\u003cmn>4\u003c/mn>\u003cmi>q\u003c/mi>\u003c/mrow>\u003c/mfrac>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|q \\alpha_* - p| \\ge \\frac{1}{q_{n+1} + q_n} = \\frac{1}{(a_{n+1} + 1) q_n + q_{n-1}} \u0026gt; \\frac{1}{4q}.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n对频率向量 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>k\u003c/mi>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>∈\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>∖\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo stretchy=\"false\">}\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">k = (k_1, k_2) \\in \\mathbb Z^2 \\setminus \\{0\\}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>：\u003c/p>\n\u003col>\n\u003cli>若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">k_1 = 0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，则 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>α\u003c/mi>\u003cmo>∗\u003c/mo>\u003c/msub>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>≥\u003c/mo>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|\\alpha_* k_1 + k_2| = |k_2| \\ge 1 \\ge \\langle k \\rangle^{-1}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>；\u003c/li>\n\u003cli>若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">k_1 \\ne 0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 且 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|k_2| \\ge 2 |k_1|\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，则 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>α\u003c/mi>\u003cmo>∗\u003c/mo>\u003c/msub>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>α\u003c/mi>\u003cmo>∗\u003c/mo>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>≥\u003c/mo>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|\\alpha_* k_1 + k_2| \\ge |k_2| - \\alpha_* |k_1| \\ge |k_1| \\ge 1 \\ge \\langle k \\rangle^{-1}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>；\u003c/li>\n\u003cli>若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">k_1 \\ne 0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 且 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>\u0026lt;\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|k_2| \u0026lt; 2 |k_1|\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，则 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>+\u003c/mo>\u003cmsubsup>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003cmn>2\u003c/mn>\u003c/msubsup>\u003cmo>+\u003c/mo>\u003cmsubsup>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003cmn>2\u003c/mn>\u003c/msubsup>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmrow>\u003cmn>1\u003c/mn>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmn>2\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmo>≤\u003c/mo>\u003cmsqrt>\u003cmn>6\u003c/mn>\u003c/msqrt>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\langle k \\rangle = (1 + k_1^2 + k_2^2)^{1/2} \\le \\sqrt{6} |k_1|\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，故\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>α\u003c/mi>\u003cmo>∗\u003c/mo>\u003c/msub>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmrow>\u003cmn>4\u003c/mn>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003c/mfrac>\u003cmo>≥\u003c/mo>\u003cmfrac>\u003cmsqrt>\u003cmn>6\u003c/mn>\u003c/msqrt>\u003cmn>4\u003c/mn>\u003c/mfrac>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|\\alpha_* k_1 + k_2| \\ge \\frac{1}{4 |k_1|} \\ge \\frac{\\sqrt{6}}{4} \\langle k \\rangle^{-1}.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n取 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>c\u003c/mi>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmsqrt>\u003cmn>6\u003c/mn>\u003c/msqrt>\u003cmn>4\u003c/mn>\u003c/mfrac>\u003cmo>\u0026gt;\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">c = \\frac{\\sqrt{6}}{4} \u0026gt; 0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，即有 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>α\u003c/mi>\u003cmo>∗\u003c/mo>\u003c/msub>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmi>c\u003c/mi>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|\\alpha_* k_1 + k_2| \\ge c \\langle k \\rangle^{-1}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 对所有非零频率成立。故 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>s\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">s = 1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 是允许的损失。\u003c/li>\n\u003c/ol>\n\u003cp>若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>s\u003c/mi>\u003cmo>\u0026lt;\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">s \u0026lt; 1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，取 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>α\u003c/mi>\u003cmo>∗\u003c/mo>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\alpha_*\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的渐近分数序列 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">p_n/q_n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，设 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>k\u003c/mi>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>n\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">k^{(n)} = (q_n, -p_n)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，则 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi>α\u003c/mi>\u003cmo>∗\u003c/mo>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmrow>\u003cmi>n\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msub>\u003c/mfrac>\u003cmo>≤\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003c/mrow>\u003c/mfrac>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|q_n \\alpha_* - p_n| \\le \\frac{1}{q_{n+1}} \\le \\frac{1}{2 q_n}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，故\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmsup>\u003cmi>k\u003c/mi>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>n\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmi>s\u003c/mi>\u003c/msup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>α\u003c/mi>\u003cmo>∗\u003c/mo>\u003c/msub>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmi>C\u003c/mi>\u003cmsubsup>\u003cmi>q\u003c/mi>\u003cmi>n\u003c/mi>\u003cmi>s\u003c/mi>\u003c/msubsup>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003c/mfrac>\u003cmo>=\u003c/mo>\u003cmi>C\u003c/mi>\u003cmsubsup>\u003cmi>q\u003c/mi>\u003cmi>n\u003c/mi>\u003cmrow>\u003cmi>s\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msubsup>\u003cmo>→\u003c/mo>\u003cmn>0\u003c/mn>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>n\u003c/mi>\u003cmo>→\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\langle k^{(n)} \\rangle^s |\\alpha_* q_n - p_n| \\le C q_n^s \\frac{1}{q_n} = C q_n^{s-1} \\to 0 \\quad (n \\to \\infty).\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n因此对任意 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>s\u003c/mi>\u003cmo>\u0026lt;\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">s \u0026lt; 1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 都不存在正下界常数 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>c\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">c\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。故 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>s\u003c/mi>\u003cmi>min\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">s_{\\min} = 1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 且在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>s\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">s = 1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 处取到。\u003c/p>\n\u003ch3>4. 连续可微模估计 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsubsup>\u003cmi>N\u003c/mi>\u003cmsub>\u003cmi>α\u003c/mi>\u003cmo>∗\u003c/mo>\u003c/msub>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msubsup>\u003cmi>F\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>C\u003c/mi>\u003cmi>m\u003c/mi>\u003c/msup>\u003c/msub>\u003cmo>≤\u003c/mo>\u003cmsub>\u003cmi>C\u003c/mi>\u003cmi>m\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>F\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>C\u003c/mi>\u003cmrow>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>4\u003c/mn>\u003c/mrow>\u003c/msup>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\|N_{\\alpha_*}^{-1} F\\|_{C^m} \\le C_m \\|F\\|_{C^{m+4}}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/h3>\n\u003cp>\u003cstrong>结论\u003c/strong>：\u003cstrong>成立\u003c/strong>。\u003c/p>\n\u003cp>\u003cstrong>证明\u003c/strong>：\n令 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>u\u003c/mi>\u003cmo>=\u003c/mo>\u003cmsubsup>\u003cmi>N\u003c/mi>\u003cmsub>\u003cmi>α\u003c/mi>\u003cmo>∗\u003c/mo>\u003c/msub>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msubsup>\u003cmi>F\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsubsup>\u003cmi>C\u003c/mi>\u003cmn>0\u003c/mn>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/msubsup>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">T\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">u = N_{\\alpha_*}^{-1} F \\in C_0^\\infty(\\mathbb T^2)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。对任意满足 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>a\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>b\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmi>m\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">a+b \\le m\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的导数，\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsubsup>\u003cmi mathvariant=\"normal\">∂\u003c/mi>\u003cmsub>\u003cmi>y\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmi>a\u003c/mi>\u003c/msubsup>\u003cmsubsup>\u003cmi mathvariant=\"normal\">∂\u003c/mi>\u003cmsub>\u003cmi>y\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmi>b\u003c/mi>\u003c/msubsup>\u003cmi>u\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmunder>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi>k\u003c/mi>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003c/munder>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>i\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi>a\u003c/mi>\u003c/msup>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>i\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi>b\u003c/mi>\u003c/msup>\u003cmfrac>\u003cmrow>\u003cmover accent=\"true\">\u003cmi>F\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>i\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>α\u003c/mi>\u003cmo>∗\u003c/mo>\u003c/msub>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/mfrac>\u003cmsup>\u003cmi>e\u003c/mi>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>i\u003c/mi>\u003cmi>k\u003c/mi>\u003cmo>⋅\u003c/mo>\u003cmi>y\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\partial_{y_1}^a \\partial_{y_2}^b u(y) = \\sum_{k \\ne 0} (2\\pi i k_1)^a (2\\pi i k_2)^b \\frac{\\widehat{F}(k)}{2\\pi i (\\alpha_* k_1 + k_2)} e^{2\\pi i k \\cdot y}.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n利用 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>s\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">s = 1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 时的下界 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>α\u003c/mi>\u003cmo>∗\u003c/mo>\u003c/msub>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmi>c\u003c/mi>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|\\alpha_* k_1 + k_2| \\ge c \\langle k \\rangle^{-1}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsubsup>\u003cmi mathvariant=\"normal\">∂\u003c/mi>\u003cmsub>\u003cmi>y\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmi>a\u003c/mi>\u003c/msubsup>\u003cmsubsup>\u003cmi mathvariant=\"normal\">∂\u003c/mi>\u003cmsub>\u003cmi>y\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmi>b\u003c/mi>\u003c/msubsup>\u003cmi>u\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>C\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msup>\u003c/msub>\u003cmo>≤\u003c/mo>\u003cmunder>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi>k\u003c/mi>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003c/munder>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmrow>\u003cmi>m\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmi>m\u003c/mi>\u003c/msup>\u003cmfrac>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmover accent=\"true\">\u003cmi>F\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>α\u003c/mi>\u003cmo>∗\u003c/mo>\u003c/msub>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003c/mfrac>\u003cmo>≤\u003c/mo>\u003cmfrac>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmrow>\u003cmi>m\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003c/mrow>\u003cmi>c\u003c/mi>\u003c/mfrac>\u003cmunder>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi>k\u003c/mi>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003c/munder>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmrow>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmover accent=\"true\">\u003cmi>F\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\|\\partial_{y_1}^a \\partial_{y_2}^b u\\|_{C^0} \\le \\sum_{k \\ne 0} (2\\pi)^{m-1} \\langle k \\rangle^m \\frac{|\\widehat{F}(k)|}{|\\alpha_* k_1 + k_2|} \\le \\frac{(2\\pi)^{m-1}}{c} \\sum_{k \\ne 0} \\langle k \\rangle^{m+1} |\\widehat{F}(k)|.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n另一方面，通过分部积分，对任意非零 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>k\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">k\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>i\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmrow>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>4\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmover accent=\"true\">\u003cmi>F\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmo>∫\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">T\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/msub>\u003cmsubsup>\u003cmi mathvariant=\"normal\">∂\u003c/mi>\u003cmsub>\u003cmi>y\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmrow>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>4\u003c/mn>\u003c/mrow>\u003c/msubsup>\u003cmi>F\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsup>\u003cmi>e\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>i\u003c/mi>\u003cmi>k\u003c/mi>\u003cmo>⋅\u003c/mo>\u003cmi>y\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmi>d\u003c/mi>\u003cmi>y\u003c/mi>\u003cmtext>  \u003c/mtext>\u003cmo>⟹\u003c/mo>\u003cmtext>  \u003c/mtext>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmsup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmrow>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>4\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmover accent=\"true\">\u003cmi>F\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsubsup>\u003cmi mathvariant=\"normal\">∂\u003c/mi>\u003cmsub>\u003cmi>y\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmrow>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>4\u003c/mn>\u003c/mrow>\u003c/msubsup>\u003cmi>F\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>C\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msup>\u003c/msub>\u003cmo>≤\u003c/mo>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>F\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>C\u003c/mi>\u003cmrow>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>4\u003c/mn>\u003c/mrow>\u003c/msup>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">(2\\pi i k_1)^{m+4} \\widehat{F}(k) = \\int_{\\mathbb T^2} \\partial_{y_1}^{m+4} F(y) e^{-2\\pi i k \\cdot y} dy \\implies |2\\pi k_1|^{m+4} |\\widehat{F}(k)| \\le \\|\\partial_{y_1}^{m+4} F\\|_{C^0} \\le \\|F\\|_{C^{m+4}},\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>i\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmrow>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>4\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmover accent=\"true\">\u003cmi>F\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmo>∫\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">T\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/msub>\u003cmsubsup>\u003cmi mathvariant=\"normal\">∂\u003c/mi>\u003cmsub>\u003cmi>y\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmrow>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>4\u003c/mn>\u003c/mrow>\u003c/msubsup>\u003cmi>F\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsup>\u003cmi>e\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>i\u003c/mi>\u003cmi>k\u003c/mi>\u003cmo>⋅\u003c/mo>\u003cmi>y\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmi>d\u003c/mi>\u003cmi>y\u003c/mi>\u003cmtext>  \u003c/mtext>\u003cmo>⟹\u003c/mo>\u003cmtext>  \u003c/mtext>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmsup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmrow>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>4\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmover accent=\"true\">\u003cmi>F\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsubsup>\u003cmi mathvariant=\"normal\">∂\u003c/mi>\u003cmsub>\u003cmi>y\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmrow>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>4\u003c/mn>\u003c/mrow>\u003c/msubsup>\u003cmi>F\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>C\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msup>\u003c/msub>\u003cmo>≤\u003c/mo>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>F\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>C\u003c/mi>\u003cmrow>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>4\u003c/mn>\u003c/mrow>\u003c/msup>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">(2\\pi i k_2)^{m+4} \\widehat{F}(k) = \\int_{\\mathbb T^2} \\partial_{y_2}^{m+4} F(y) e^{-2\\pi i k \\cdot y} dy \\implies |2\\pi k_2|^{m+4} |\\widehat{F}(k)| \\le \\|\\partial_{y_2}^{m+4} F\\|_{C^0} \\le \\|F\\|_{C^{m+4}}.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n由初等不等式 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmrow>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>4\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmo>≤\u003c/mo>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>m\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmsup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmrow>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>4\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmo>+\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmsup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmrow>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>4\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\langle k \\rangle^{m+4} \\le A_m (|k_1|^{m+4} + |k_2|^{m+4})\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 对 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>k\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>∖\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo stretchy=\"false\">}\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">k \\in \\mathbb Z^2 \\setminus \\{0\\}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 成立，存在有限常数 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>K\u003c/mi>\u003cmi>m\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">K_m\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 满足：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmover accent=\"true\">\u003cmi>F\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmsub>\u003cmi>K\u003c/mi>\u003cmi>m\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>4\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>F\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>C\u003c/mi>\u003cmrow>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>4\u003c/mn>\u003c/mrow>\u003c/msup>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|\\widehat{F}(k)| \\le K_m \\langle k \\rangle^{-(m+4)} \\|F\\|_{C^{m+4}}.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n将此式代入前述导数和式中：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmunder>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi>k\u003c/mi>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003c/munder>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmrow>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmover accent=\"true\">\u003cmi>F\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmsub>\u003cmi>K\u003c/mi>\u003cmi>m\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>F\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>C\u003c/mi>\u003cmrow>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>4\u003c/mn>\u003c/mrow>\u003c/msup>\u003c/msub>\u003cmunder>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi>k\u003c/mi>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003c/munder>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmrow>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>−\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>4\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>K\u003c/mi>\u003cmi>m\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>F\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>C\u003c/mi>\u003cmrow>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>4\u003c/mn>\u003c/mrow>\u003c/msup>\u003c/msub>\u003cmunder>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi>k\u003c/mi>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003c/munder>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>3\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\sum_{k \\ne 0} \\langle k \\rangle^{m+1} |\\widehat{F}(k)| \\le K_m \\|F\\|_{C^{m+4}} \\sum_{k \\ne 0} \\langle k \\rangle^{m+1 - (m+4)} = K_m \\|F\\|_{C^{m+4}} \\sum_{k \\ne 0} \\langle k \\rangle^{-3}.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n在二维环面上，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi>k\u003c/mi>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>3\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmo>≤\u003c/mo>\u003cmsubsup>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi>R\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/msubsup>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>8\u003c/mn>\u003cmi>R\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsup>\u003cmi>R\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>3\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmo>=\u003c/mo>\u003cmn>8\u003c/mn>\u003cmsubsup>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi>R\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/msubsup>\u003cmsup>\u003cmi>R\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmo>\u0026lt;\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\sum_{k \\ne 0} \\langle k \\rangle^{-3} \\le \\sum_{R=1}^\\infty (8R) R^{-3} = 8 \\sum_{R=1}^\\infty R^{-2} \u0026lt; \\infty\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\n记 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>S\u003c/mi>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi>k\u003c/mi>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>3\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmo>\u0026lt;\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">S = \\sum_{k \\ne 0} \\langle k \\rangle^{-3} \u0026lt; \\infty\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，则对所有 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>a\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>b\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmi>m\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">a+b \\le m\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmunder>\u003cmrow>\u003cmi>sup\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmi>y\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">T\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003c/munder>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsubsup>\u003cmi mathvariant=\"normal\">∂\u003c/mi>\u003cmsub>\u003cmi>y\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmi>a\u003c/mi>\u003c/msubsup>\u003cmsubsup>\u003cmi mathvariant=\"normal\">∂\u003c/mi>\u003cmsub>\u003cmi>y\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmi>b\u003c/mi>\u003c/msubsup>\u003cmi>u\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmfrac>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmrow>\u003cmi>m\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmsub>\u003cmi>K\u003c/mi>\u003cmi>m\u003c/mi>\u003c/msub>\u003cmi>S\u003c/mi>\u003c/mrow>\u003cmi>c\u003c/mi>\u003c/mfrac>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>F\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>C\u003c/mi>\u003cmrow>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>4\u003c/mn>\u003c/mrow>\u003c/msup>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\sup_{y \\in \\mathbb T^2} |\\partial_{y_1}^a \\partial_{y_2}^b u(y)| \\le \\frac{(2\\pi)^{m-1} K_m S}{c} \\|F\\|_{C^{m+4}}.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n取有限常数 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>C\u003c/mi>\u003cmi>m\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmrow>\u003cmi>m\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmsub>\u003cmi>K\u003c/mi>\u003cmi>m\u003c/mi>\u003c/msub>\u003cmi>S\u003c/mi>\u003c/mrow>\u003cmi>c\u003c/mi>\u003c/mfrac>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">C_m = \\frac{(2\\pi)^{m-1} K_m S}{c}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，即证：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsubsup>\u003cmi>N\u003c/mi>\u003cmsub>\u003cmi>α\u003c/mi>\u003cmo>∗\u003c/mo>\u003c/msub>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msubsup>\u003cmi>F\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>C\u003c/mi>\u003cmi>m\u003c/mi>\u003c/msup>\u003c/msub>\u003cmo>≤\u003c/mo>\u003cmsub>\u003cmi>C\u003c/mi>\u003cmi>m\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>F\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>C\u003c/mi>\u003cmrow>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>4\u003c/mn>\u003c/mrow>\u003c/msup>\u003c/msub>\u003cmspace width=\"2em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi mathvariant=\"normal\">∀\u003c/mi>\u003cmi>F\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsubsup>\u003cmi>C\u003c/mi>\u003cmn>0\u003c/mn>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/msubsup>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">T\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\|N_{\\alpha_*}^{-1} F\\|_{C^m} \\le C_m \\|F\\|_{C^{m+4}} \\qquad (\\forall F \\in C_0^\\infty(\\mathbb T^2)).\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003chr>\n\u003ch2>S5 邻近方向的一致估计\u003c/h2>\n\u003ch3>1. 结论\u003c/h3>\n\u003cp>\u003cstrong>不存在\u003c/strong> 满足要求的开区间 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>J\u003c/mi>\u003cmo>∋\u003c/mo>\u003cmsub>\u003cmi>α\u003c/mi>\u003cmo>∗\u003c/mo>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">J \\ni \\alpha_*\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>、有限 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>s\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">s \\ge 0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 及常数 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>C\u003c/mi>\u003cmo>\u0026lt;\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">C \u0026lt; \\infty\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003ch3>2. 完整证明（反证法）\u003c/h3>\n\u003cp>反设存在开区间 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>J\u003c/mi>\u003cmo>∋\u003c/mo>\u003cmsub>\u003cmi>α\u003c/mi>\u003cmo>∗\u003c/mo>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">J \\ni \\alpha_*\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>、有限 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>s\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">s \\ge 0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 及 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>C\u003c/mi>\u003cmo>\u0026lt;\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">C \u0026lt; \\infty\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，使得对所有无理数 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>α\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmi>J\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\alpha \\in J\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 及所有 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>u\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsubsup>\u003cmi>C\u003c/mi>\u003cmn>0\u003c/mn>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/msubsup>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">T\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">u \\in C_0^\\infty(\\mathbb T^2)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，均有\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>u\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>L\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/msub>\u003cmo>≤\u003c/mo>\u003cmi>C\u003c/mi>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsub>\u003cmi>N\u003c/mi>\u003cmi>α\u003c/mi>\u003c/msub>\u003cmi>u\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>H\u003c/mi>\u003cmi>s\u003c/mi>\u003c/msup>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\|u\\|_{L^2} \\le C \\|N_\\alpha u\\|_{H^s}.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003cp>\u003cstrong>步骤 1：频率模测试\u003c/strong>\n对任意固定非零整频率 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>k\u003c/mi>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>∈\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>∖\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo stretchy=\"false\">}\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">k = (k_1, k_2) \\in \\mathbb Z^2 \\setminus \\{0\\}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，选取单模函数\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmsup>\u003cmi>e\u003c/mi>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>i\u003c/mi>\u003cmi>k\u003c/mi>\u003cmo>⋅\u003c/mo>\u003cmi>y\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">u_k(y) = e^{2\\pi i k \\cdot y}.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n显然 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msub>\u003cmo>∈\u003c/mo>\u003cmsubsup>\u003cmi>C\u003c/mi>\u003cmn>0\u003c/mn>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/msubsup>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">T\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">u_k \\in C_0^\\infty(\\mathbb T^2)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，其模长满足 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>L\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\|u_k\\|_{L^2} = 1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\n由于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>N\u003c/mi>\u003cmi>α\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>i\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>α\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsup>\u003cmi>e\u003c/mi>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>i\u003c/mi>\u003cmi>k\u003c/mi>\u003cmo>⋅\u003c/mo>\u003cmi>y\u003c/mi>\u003c/mrow>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">N_\\alpha u_k(y) = 2\\pi i (\\alpha k_1 + k_2) e^{2\\pi i k \\cdot y}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，其 Sobolev 范数为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsub>\u003cmi>N\u003c/mi>\u003cmi>α\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>H\u003c/mi>\u003cmi>s\u003c/mi>\u003c/msup>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>α\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmi>s\u003c/mi>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\|N_\\alpha u_k\\|_{H^s} = 2\\pi |\\alpha k_1 + k_2| \\langle k \\rangle^s.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n代入假设的不等式即得：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmn>1\u003c/mn>\u003cmo>≤\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>C\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>α\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmi>s\u003c/mi>\u003c/msup>\u003cmtext>  \u003c/mtext>\u003cmo>⟺\u003c/mo>\u003cmtext>  \u003c/mtext>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>α\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>C\u003c/mi>\u003c/mrow>\u003c/mfrac>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmi>k\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmi>s\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">1 \\le 2\\pi C |\\alpha k_1 + k_2| \\langle k \\rangle^s \\iff |\\alpha k_1 + k_2| \\ge \\frac{1}{2\\pi C} \\langle k \\rangle^{-s},\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n此不等式必须对区间 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>J\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">J\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 内的 \u003cstrong>每一个\u003c/strong> 无理数 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>α\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\alpha\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 及 \u003cstrong>每一个\u003c/strong> 非零频率 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>k\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">k\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 均成立。\u003c/p>\n\u003cp>\u003cstrong>步骤 2：构造邻近有理点的反例方向\u003c/strong>\n由于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>J\u003c/mi>\u003cmo>⊂\u003c/mo>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">J \\subset \\mathbb R\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 为包含 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>α\u003c/mi>\u003cmo>∗\u003c/mo>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\alpha_*\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的开区间，有理数集 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"double-struck\">Q\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathbb Q\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>J\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">J\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 中稠密。\n在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>J\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">J\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 中任取一个有理数 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>p\u003c/mi>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmi>q\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmi>J\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">p/q \\in J\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，其中 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>q\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmi mathvariant=\"double-struck\">N\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>p\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">q \\in \\mathbb N, p \\in \\mathbb Z\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\n因为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>J\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">J\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 为开集，存在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>ε\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo>\u0026gt;\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\varepsilon_0 \u0026gt; 0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 使得开邻域 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">[\u003c/mo>\u003cmi>p\u003c/mi>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmi>q\u003c/mi>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>ε\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>p\u003c/mi>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmi>q\u003c/mi>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>ε\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">]\u003c/mo>\u003cmo>⊂\u003c/mo>\u003cmi>J\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">[p/q - \\varepsilon_0, p/q + \\varepsilon_0] \\subset J\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\n固定整频率向量为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>k\u003c/mi>\u003cmo>∗\u003c/mo>\u003c/msup>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>q\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmo>−\u003c/mo>\u003cmi>p\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>∈\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>∖\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">k^* = (q, -p) \\in \\mathbb Z^2 \\setminus \\{0\\}.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n此时 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmsup>\u003cmi>k\u003c/mi>\u003cmo>∗\u003c/mo>\u003c/msup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>+\u003c/mo>\u003cmsup>\u003cmi>q\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>+\u003c/mo>\u003cmsup>\u003cmi>p\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmrow>\u003cmn>1\u003c/mn>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmn>2\u003c/mn>\u003c/mrow>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\langle k^* \\rangle = (1 + q^2 + p^2)^{1/2}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 为一固定的有限正数。\n考虑微扰参数 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>ε\u003c/mi>\u003cmo>\u0026gt;\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\varepsilon \u0026gt; 0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，定义方向：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>α\u003c/mi>\u003cmi>ε\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmi>p\u003c/mi>\u003cmi>q\u003c/mi>\u003c/mfrac>\u003cmo>+\u003c/mo>\u003cmfrac>\u003cmi>ε\u003c/mi>\u003cmsqrt>\u003cmn>2\u003c/mn>\u003c/msqrt>\u003c/mfrac>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\alpha_\\varepsilon = \\frac{p}{q} + \\frac{\\varepsilon}{\\sqrt{2}}.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n只要 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>0\u003c/mn>\u003cmo>\u0026lt;\u003c/mo>\u003cmi>ε\u003c/mi>\u003cmo>\u0026lt;\u003c/mo>\u003cmsub>\u003cmi>ε\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmsqrt>\u003cmn>2\u003c/mn>\u003c/msqrt>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">0 \u0026lt; \\varepsilon \u0026lt; \\varepsilon_0 \\sqrt{2}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，便有 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>α\u003c/mi>\u003cmi>ε\u003c/mi>\u003c/msub>\u003cmo>∈\u003c/mo>\u003cmi>J\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\alpha_\\varepsilon \\in J\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>；且由于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsqrt>\u003cmn>2\u003c/mn>\u003c/msqrt>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\sqrt{2}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 是无理数，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>α\u003c/mi>\u003cmi>ε\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\alpha_\\varepsilon\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 必为无理数。\n在此方向下计算小除数：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>α\u003c/mi>\u003cmi>ε\u003c/mi>\u003c/msub>\u003cmsubsup>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003cmo>∗\u003c/mo>\u003c/msubsup>\u003cmo>+\u003c/mo>\u003cmsubsup>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003cmo>∗\u003c/mo>\u003c/msubsup>\u003cmo>=\u003c/mo>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmfrac>\u003cmi>p\u003c/mi>\u003cmi>q\u003c/mi>\u003c/mfrac>\u003cmo>+\u003c/mo>\u003cmfrac>\u003cmi>ε\u003c/mi>\u003cmsqrt>\u003cmn>2\u003c/mn>\u003c/msqrt>\u003c/mfrac>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cmi>q\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>p\u003c/mi>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmrow>\u003cmi>q\u003c/mi>\u003cmi>ε\u003c/mi>\u003c/mrow>\u003cmsqrt>\u003cmn>2\u003c/mn>\u003c/msqrt>\u003c/mfrac>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\alpha_\\varepsilon k_1^* + k_2^* = \\left(\\frac{p}{q} + \\frac{\\varepsilon}{\\sqrt{2}}\\right) q - p = \\frac{q \\varepsilon}{\\sqrt{2}}.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n现在选取满足下列条件的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>ε\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\varepsilon\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmn>0\u003c/mn>\u003cmo>\u0026lt;\u003c/mo>\u003cmi>ε\u003c/mi>\u003cmo>\u0026lt;\u003c/mo>\u003cmi>min\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmrow>\u003cmo fence=\"true\">{\u003c/mo>\u003cmsub>\u003cmi>ε\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmsqrt>\u003cmn>2\u003c/mn>\u003c/msqrt>\u003cmo separator=\"true\">,\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmfrac>\u003cmsqrt>\u003cmn>2\u003c/mn>\u003c/msqrt>\u003cmrow>\u003cmn>4\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>C\u003c/mi>\u003cmi>q\u003c/mi>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmsup>\u003cmi>k\u003c/mi>\u003cmo>∗\u003c/mo>\u003c/msup>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmi>s\u003c/mi>\u003c/msup>\u003c/mrow>\u003c/mfrac>\u003cmo fence=\"true\">}\u003c/mo>\u003c/mrow>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">0 \u0026lt; \\varepsilon \u0026lt; \\min\\left\\{ \\varepsilon_0 \\sqrt{2}, \\ \\frac{\\sqrt{2}}{4\\pi C q \\langle k^* \\rangle^s} \\right\\}.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n对于此无理数 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>α\u003c/mi>\u003cmi>ε\u003c/mi>\u003c/msub>\u003cmo>∈\u003c/mo>\u003cmi>J\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\alpha_\\varepsilon \\in J\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，小除数满足：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>α\u003c/mi>\u003cmi>ε\u003c/mi>\u003c/msub>\u003cmsubsup>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003cmo>∗\u003c/mo>\u003c/msubsup>\u003cmo>+\u003c/mo>\u003cmsubsup>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003cmo>∗\u003c/mo>\u003c/msubsup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmrow>\u003cmi>q\u003c/mi>\u003cmi>ε\u003c/mi>\u003c/mrow>\u003cmsqrt>\u003cmn>2\u003c/mn>\u003c/msqrt>\u003c/mfrac>\u003cmo>\u0026lt;\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmrow>\u003cmn>4\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>C\u003c/mi>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmsup>\u003cmi>k\u003c/mi>\u003cmo>∗\u003c/mo>\u003c/msup>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmi>s\u003c/mi>\u003c/msup>\u003c/mrow>\u003c/mfrac>\u003cmo>\u0026lt;\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>C\u003c/mi>\u003c/mrow>\u003c/mfrac>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmsup>\u003cmi>k\u003c/mi>\u003cmo>∗\u003c/mo>\u003c/msup>\u003cmsup>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmi>s\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|\\alpha_\\varepsilon k_1^* + k_2^*| = \\frac{q \\varepsilon}{\\sqrt{2}} \u0026lt; \\frac{1}{4\\pi C \\langle k^* \\rangle^s} \u0026lt; \\frac{1}{2\\pi C} \\langle k^* \\rangle^{-s}.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n这直接违背了步骤 1 中必须成立的必要条件！\n此外，任意开区间 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>J\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">J\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 中均包含不可数个 Liouville 数，对于任意单个 Liouville 数方向，均不存在有限的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>C\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>s\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">(C, s)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 使得该先验估计成立。因此该一致估计在任何开区间上均不可能成立。\u003c/p>\n\u003chr>\n\u003ch2>S6 一个具体方向的不可解数据\u003c/h2>\n\u003ch3>1. 证明 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>α\u003c/mi>\u003cmo>=\u003c/mo>\u003cmsubsup>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi>n\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/msubsup>\u003cmsup>\u003cmn>10\u003c/mn>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmi>n\u003c/mi>\u003cmo stretchy=\"false\">!\u003c/mo>\u003c/mrow>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\alpha = \\sum_{n=1}^\\infty 10^{-n!}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 是无理数\u003c/h3>\n\u003cp>对每个正整数 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>m\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">m \\ge 1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，令\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>m\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsup>\u003cmn>10\u003c/mn>\u003cmrow>\u003cmi>m\u003c/mi>\u003cmo stretchy=\"false\">!\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmi>m\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmunderover>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi>n\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cmi>m\u003c/mi>\u003c/munderover>\u003cmsup>\u003cmn>10\u003c/mn>\u003cmrow>\u003cmi>m\u003c/mi>\u003cmo stretchy=\"false\">!\u003c/mo>\u003cmo>−\u003c/mo>\u003cmi>n\u003c/mi>\u003cmo stretchy=\"false\">!\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmo>∈\u003c/mo>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">q_m = 10^{m!}, \\qquad p_m = \\sum_{n=1}^m 10^{m! - n!} \\in \\mathbb Z.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n显然 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>m\u003c/mi>\u003c/msub>\u003cmo>∈\u003c/mo>\u003cmi mathvariant=\"double-struck\">N\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmi>m\u003c/mi>\u003c/msub>\u003cmo>∈\u003c/mo>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">q_m \\in \\mathbb N, p_m \\in \\mathbb Z\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，且有理数逼近项为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmfrac>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmi>m\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>m\u003c/mi>\u003c/msub>\u003c/mfrac>\u003cmo>=\u003c/mo>\u003cmunderover>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi>n\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cmi>m\u003c/mi>\u003c/munderover>\u003cmsup>\u003cmn>10\u003c/mn>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmi>n\u003c/mi>\u003cmo stretchy=\"false\">!\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\frac{p_m}{q_m} = \\sum_{n=1}^m 10^{-n!}.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n考察尾项级数：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmn>0\u003c/mn>\u003cmo>\u0026lt;\u003c/mo>\u003cmi>α\u003c/mi>\u003cmo>−\u003c/mo>\u003cmfrac>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmi>m\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>m\u003c/mi>\u003c/msub>\u003c/mfrac>\u003cmo>=\u003c/mo>\u003cmunderover>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi>n\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/munderover>\u003cmsup>\u003cmn>10\u003c/mn>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmi>n\u003c/mi>\u003cmo stretchy=\"false\">!\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmo>=\u003c/mo>\u003cmsup>\u003cmn>10\u003c/mn>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">!\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>+\u003c/mo>\u003cmunderover>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi>n\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/munderover>\u003cmsup>\u003cmn>10\u003c/mn>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>n\u003c/mi>\u003cmo stretchy=\"false\">!\u003c/mo>\u003cmo>−\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">!\u003c/mo>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">0 \u0026lt; \\alpha - \\frac{p_m}{q_m} = \\sum_{n=m+1}^\\infty 10^{-n!} = 10^{-(m+1)!} \\left( 1 + \\sum_{n=m+2}^\\infty 10^{-(n! - (m+1)!)} \\right).\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n由于对 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>n\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">n \\ge m+2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 有 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>n\u003c/mi>\u003cmo stretchy=\"false\">!\u003c/mo>\u003cmo>−\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">!\u003c/mo>\u003cmo>≥\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">!\u003c/mo>\u003cmo>−\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">!\u003c/mo>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>⋅\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">!\u003c/mo>\u003cmo>≥\u003c/mo>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>n\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>m\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">n! - (m+1)! \\ge (m+2)! - (m+1)! = (m+1) \\cdot (m+1)! \\ge 2(n - m - 1)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，故公比小于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>1\u003c/mn>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmn>10\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">1/10\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmn>0\u003c/mn>\u003cmo>\u0026lt;\u003c/mo>\u003cmi>α\u003c/mi>\u003cmo>−\u003c/mo>\u003cmfrac>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmi>m\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>m\u003c/mi>\u003c/msub>\u003c/mfrac>\u003cmo>\u0026lt;\u003c/mo>\u003cmsup>\u003cmn>10\u003c/mn>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">!\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmunderover>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi>j\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/munderover>\u003cmsup>\u003cmn>10\u003c/mn>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmi>j\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmn>10\u003c/mn>\u003cmn>9\u003c/mn>\u003c/mfrac>\u003cmsup>\u003cmn>10\u003c/mn>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">!\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">0 \u0026lt; \\alpha - \\frac{p_m}{q_m} \u0026lt; 10^{-(m+1)!} \\sum_{j=0}^\\infty 10^{-j} = \\frac{10}{9} 10^{-(m+1)!}.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n由于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">!\u003c/mo>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi>m\u003c/mi>\u003cmo stretchy=\"false\">!\u003c/mo>\u003cmo>=\u003c/mo>\u003cmi>m\u003c/mi>\u003cmo>⋅\u003c/mo>\u003cmi>m\u003c/mi>\u003cmo stretchy=\"false\">!\u003c/mo>\u003cmo>+\u003c/mo>\u003cmi>m\u003c/mi>\u003cmo stretchy=\"false\">!\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">(m+1)! = (m+1) m! = m \\cdot m! + m!\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，可得\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmn>10\u003c/mn>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">!\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmo>=\u003c/mo>\u003cmsup>\u003cmn>10\u003c/mn>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmi>m\u003c/mi>\u003cmo>⋅\u003c/mo>\u003cmi>m\u003c/mi>\u003cmo stretchy=\"false\">!\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmo>⋅\u003c/mo>\u003cmsup>\u003cmn>10\u003c/mn>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmi>m\u003c/mi>\u003cmo stretchy=\"false\">!\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmo>=\u003c/mo>\u003cmsubsup>\u003cmi>q\u003c/mi>\u003cmi>m\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msubsup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">10^{-(m+1)!} = 10^{-m \\cdot m!} \\cdot 10^{-m!} = q_m^{-(m+1)}.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n特别地，当 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>m\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">m \\ge 2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 时，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>m\u003c/mi>\u003c/msub>\u003cmo>≥\u003c/mo>\u003cmn>100\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">q_m \\ge 100\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，故 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>0\u003c/mn>\u003cmo>\u0026lt;\u003c/mo>\u003cmi>α\u003c/mi>\u003cmo>−\u003c/mo>\u003cmfrac>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmi>m\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>m\u003c/mi>\u003c/msub>\u003c/mfrac>\u003cmo>\u0026lt;\u003c/mo>\u003cmfrac>\u003cmn>10\u003c/mn>\u003cmn>9\u003c/mn>\u003c/mfrac>\u003cmsubsup>\u003cmi>q\u003c/mi>\u003cmi>m\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msubsup>\u003cmo>\u0026lt;\u003c/mo>\u003cmsubsup>\u003cmi>q\u003c/mi>\u003cmi>m\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmi>m\u003c/mi>\u003c/mrow>\u003c/msubsup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">0 \u0026lt; \\alpha - \\frac{p_m}{q_m} \u0026lt; \\frac{10}{9} q_m^{-(m+1)} \u0026lt; q_m^{-m}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003cp>假设 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>α\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\alpha\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 为有理数，设 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>α\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>a\u003c/mi>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmi>b\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\alpha = a/b\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>（\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>a\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>b\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmi mathvariant=\"double-struck\">N\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">a \\in \\mathbb Z, b \\in \\mathbb N\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>）。\n由于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>α\u003c/mi>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmi>m\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>m\u003c/mi>\u003c/msub>\u003cmo>\u0026gt;\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\alpha - p_m/q_m \u0026gt; 0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，对所有 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>m\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">m\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 均有 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>α\u003c/mi>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmi>m\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>m\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\alpha \\ne p_m/q_m\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。因此：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmrow>\u003cmo fence=\"true\">∣\u003c/mo>\u003cmi>α\u003c/mi>\u003cmo>−\u003c/mo>\u003cmfrac>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmi>m\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>m\u003c/mi>\u003c/msub>\u003c/mfrac>\u003cmo fence=\"true\">∣\u003c/mo>\u003c/mrow>\u003cmo>=\u003c/mo>\u003cmrow>\u003cmo fence=\"true\">∣\u003c/mo>\u003cmfrac>\u003cmi>a\u003c/mi>\u003cmi>b\u003c/mi>\u003c/mfrac>\u003cmo>−\u003c/mo>\u003cmfrac>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmi>m\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>m\u003c/mi>\u003c/msub>\u003c/mfrac>\u003cmo fence=\"true\">∣\u003c/mo>\u003c/mrow>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>a\u003c/mi>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>m\u003c/mi>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmi>b\u003c/mi>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmi>m\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003cmrow>\u003cmi>b\u003c/mi>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>m\u003c/mi>\u003c/msub>\u003c/mrow>\u003c/mfrac>\u003cmo>≥\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmrow>\u003cmi>b\u003c/mi>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>m\u003c/mi>\u003c/msub>\u003c/mrow>\u003c/mfrac>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\left| \\alpha - \\frac{p_m}{q_m} \\right| = \\left| \\frac{a}{b} - \\frac{p_m}{q_m} \\right| = \\frac{|a q_m - b p_m|}{b q_m} \\ge \\frac{1}{b q_m}.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n但根据上面的上界，当 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>m\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">m\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 充分大使得 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsubsup>\u003cmi>q\u003c/mi>\u003cmi>m\u003c/mi>\u003cmrow>\u003cmi>m\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msubsup>\u003cmo>\u0026gt;\u003c/mo>\u003cmfrac>\u003cmn>10\u003c/mn>\u003cmn>9\u003c/mn>\u003c/mfrac>\u003cmi>b\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">q_m^{m-1} \u0026gt; \\frac{10}{9} b\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 时（由于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>m\u003c/mi>\u003c/msub>\u003cmo>→\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">q_m \\to \\infty\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 且 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>m\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">m \\ge 2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，此式显然成立）：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>α\u003c/mi>\u003cmo>−\u003c/mo>\u003cmfrac>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmi>m\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>m\u003c/mi>\u003c/msub>\u003c/mfrac>\u003cmo>\u0026lt;\u003c/mo>\u003cmfrac>\u003cmn>10\u003c/mn>\u003cmn>9\u003c/mn>\u003c/mfrac>\u003cmsubsup>\u003cmi>q\u003c/mi>\u003cmi>m\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msubsup>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmn>10\u003c/mn>\u003cmrow>\u003cmn>9\u003c/mn>\u003cmsubsup>\u003cmi>q\u003c/mi>\u003cmi>m\u003c/mi>\u003cmrow>\u003cmi>m\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msubsup>\u003c/mrow>\u003c/mfrac>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmsubsup>\u003cmi>q\u003c/mi>\u003cmi>m\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msubsup>\u003c/mfrac>\u003cmo>\u0026lt;\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmrow>\u003cmi>b\u003c/mi>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>m\u003c/mi>\u003c/msub>\u003c/mrow>\u003c/mfrac>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\alpha - \\frac{p_m}{q_m} \u0026lt; \\frac{10}{9} q_m^{-(m+1)} = \\frac{10}{9 q_m^{m-1}} \\frac{1}{q_m^2} \u0026lt; \\frac{1}{b q_m},\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n产生矛盾！故 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>α\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\alpha\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 必为无理数（且为 Liouville 超越数）。\u003c/p>\n\u003ch3>2. 构造同一个光滑零均值数据 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>F\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">F\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/h3>\n\u003cp>取整频率序列：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>k\u003c/mi>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>m\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>m\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmi>m\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>∈\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmspace width=\"2em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>m\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">k^{(m)} = (q_m, -p_m) \\in \\mathbb Z^2 \\qquad (m \\ge 2).\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n因为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>m\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsup>\u003cmn>10\u003c/mn>\u003cmrow>\u003cmi>m\u003c/mi>\u003cmo stretchy=\"false\">!\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmo>≥\u003c/mo>\u003cmn>100\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">q_m = 10^{m!} \\ge 100\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，且 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>m\u003c/mi>\u003c/msub>\u003cmo>\u0026lt;\u003c/mo>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmrow>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">q_m \u0026lt; q_{m+1}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，所有频点 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>k\u003c/mi>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>m\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">k^{(m)}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 均非零且两两互异。\n由于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmi>m\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>m\u003c/mi>\u003c/msub>\u003cmo>\u0026lt;\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">p_m/q_m \u0026lt; 1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，欧氏范数满足：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>m\u003c/mi>\u003c/msub>\u003cmo>≤\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsup>\u003cmi>k\u003c/mi>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>m\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>=\u003c/mo>\u003cmsqrt>\u003cmrow>\u003cmsubsup>\u003cmi>q\u003c/mi>\u003cmi>m\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msubsup>\u003cmo>+\u003c/mo>\u003cmsubsup>\u003cmi>p\u003c/mi>\u003cmi>m\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msubsup>\u003c/mrow>\u003c/msqrt>\u003cmo>≤\u003c/mo>\u003cmsqrt>\u003cmn>2\u003c/mn>\u003c/msqrt>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>m\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">q_m \\le |k^{(m)}| = \\sqrt{q_m^2 + p_m^2} \\le \\sqrt{2} q_m.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n在各频点处的小除数绝对值为：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>α\u003c/mi>\u003cmsubsup>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>m\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msubsup>\u003cmo>+\u003c/mo>\u003cmsubsup>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>m\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msubsup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>α\u003c/mi>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>m\u003c/mi>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmi>m\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>m\u003c/mi>\u003c/msub>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmi>α\u003c/mi>\u003cmo>−\u003c/mo>\u003cmfrac>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmi>m\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>m\u003c/mi>\u003c/msub>\u003c/mfrac>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|\\alpha k_1^{(m)} + k_2^{(m)}| = |\\alpha q_m - p_m| = q_m \\left(\\alpha - \\frac{p_m}{q_m}\\right).\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n结合上式的严格上下界，有\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmn>10\u003c/mn>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmi>m\u003c/mi>\u003cmo>⋅\u003c/mo>\u003cmi>m\u003c/mi>\u003cmo stretchy=\"false\">!\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmo>\u0026lt;\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>α\u003c/mi>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>m\u003c/mi>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmi>m\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>\u0026lt;\u003c/mo>\u003cmfrac>\u003cmn>10\u003c/mn>\u003cmn>9\u003c/mn>\u003c/mfrac>\u003cmsup>\u003cmn>10\u003c/mn>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmi>m\u003c/mi>\u003cmo>⋅\u003c/mo>\u003cmi>m\u003c/mi>\u003cmo stretchy=\"false\">!\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">10^{-m \\cdot m!} \u0026lt; |\\alpha q_m - p_m| \u0026lt; \\frac{10}{9} 10^{-m \\cdot m!}.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n定义单一的光滑零均值函数 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsubsup>\u003cmi>C\u003c/mi>\u003cmn>0\u003c/mn>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/msubsup>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">T\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">F \\in C_0^\\infty(\\mathbb T^2)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，其 Fourier 系数设定为：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmover accent=\"true\">\u003cmi>F\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmrow>\u003cmo fence=\"true\">{\u003c/mo>\u003cmtable rowspacing=\"0.36em\" columnalign=\"left left\" columnspacing=\"1em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmsup>\u003cmn>10\u003c/mn>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmi>m\u003c/mi>\u003cmo>⋅\u003c/mo>\u003cmi>m\u003c/mi>\u003cmo stretchy=\"false\">!\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmi>k\u003c/mi>\u003cmo>=\u003c/mo>\u003cmsup>\u003cmi>k\u003c/mi>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>m\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>m\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmtext>其他 \u003c/mtext>\u003cmi>k\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003c/mrow>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\widehat{F}(k) = \\begin{cases}\n10^{-\\frac{1}{2} m \\cdot m!}, \u0026amp; k = k^{(m)} \\quad (m \\ge 2), \\\\\n0, \u0026amp; \\text{其他 } k \\in \\mathbb Z^2.\n\\end{cases}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n即：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmunderover>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi>m\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/munderover>\u003cmsup>\u003cmn>10\u003c/mn>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmi>m\u003c/mi>\u003cmo>⋅\u003c/mo>\u003cmi>m\u003c/mi>\u003cmo stretchy=\"false\">!\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmsup>\u003cmi>e\u003c/mi>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>i\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>m\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi>y\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmi>m\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi>y\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">F(y) = \\sum_{m=2}^\\infty 10^{-\\frac{1}{2} m \\cdot m!} e^{2\\pi i (q_m y_1 - p_m y_2)}.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003ch3>3. 性质与无解性证明\u003c/h3>\n\u003col>\n\u003cli>\u003cstrong>零均值\u003c/strong>：各 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>k\u003c/mi>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>m\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">k^{(m)} \\ne (0,0)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，故 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmo>∫\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">T\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/msub>\u003cmi>F\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi>d\u003c/mi>\u003cmi>y\u003c/mi>\u003cmo>=\u003c/mo>\u003cmover accent=\"true\">\u003cmi>F\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\int_{\\mathbb T^2} F(y) dy = \\widehat{F}(0) = 0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/li>\n\u003cli>\u003cstrong>光滑性\u003c/strong>：对任意阶导数指标 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>β\u003c/mi>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>a\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>b\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>∈\u003c/mo>\u003cmsubsup>\u003cmi mathvariant=\"double-struck\">N\u003c/mi>\u003cmn>0\u003c/mn>\u003cmn>2\u003c/mn>\u003c/msubsup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\beta = (a, b) \\in \\mathbb N_0^2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>（记 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>β\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>a\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>b\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|\\beta| = a+b\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>）：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmrow>\u003cmo fence=\"true\">∣\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"normal\">∂\u003c/mi>\u003cmi>β\u003c/mi>\u003c/msup>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmover accent=\"true\">\u003cmi>F\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmi>k\u003c/mi>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>m\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsup>\u003cmi>e\u003c/mi>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>i\u003c/mi>\u003cmsup>\u003cmi>k\u003c/mi>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>m\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmo>⋅\u003c/mo>\u003cmi>y\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cmo fence=\"true\">∣\u003c/mo>\u003c/mrow>\u003cmo>≤\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>β\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmsubsup>\u003cmi>q\u003c/mi>\u003cmi>m\u003c/mi>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>β\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003c/msubsup>\u003cmsup>\u003cmn>10\u003c/mn>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmi>m\u003c/mi>\u003cmo>⋅\u003c/mo>\u003cmi>m\u003c/mi>\u003cmo stretchy=\"false\">!\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>β\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmsup>\u003cmn>10\u003c/mn>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>β\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>m\u003c/mi>\u003cmo stretchy=\"false\">!\u003c/mo>\u003cmo>−\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmi>m\u003c/mi>\u003cmo>⋅\u003c/mo>\u003cmi>m\u003c/mi>\u003cmo stretchy=\"false\">!\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>β\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmsup>\u003cmn>10\u003c/mn>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmfrac>\u003cmi>m\u003c/mi>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmo>−\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>β\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cmi>m\u003c/mi>\u003cmo stretchy=\"false\">!\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\left| \\partial^\\beta \\left( \\widehat{F}(k^{(m)}) e^{2\\pi i k^{(m)} \\cdot y} \\right) \\right| \\le (2\\pi)^{|\\beta|} q_m^{|\\beta|} 10^{-\\frac{1}{2} m \\cdot m!} = (2\\pi)^{|\\beta|} 10^{|\\beta| m! - \\frac{1}{2} m \\cdot m!} = (2\\pi)^{|\\beta|} 10^{-\\left(\\frac{m}{2} - |\\beta|\\right) m!}.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n当 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>m\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>β\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">m \\ge 2|\\beta| + 2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 时，指数满足 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmfrac>\u003cmi>m\u003c/mi>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmo>−\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>β\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cmi>m\u003c/mi>\u003cmo stretchy=\"false\">!\u003c/mo>\u003cmo>≥\u003c/mo>\u003cmi>m\u003c/mi>\u003cmo stretchy=\"false\">!\u003c/mo>\u003cmo>≥\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>m\u003c/mi>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\left(\\frac{m}{2} - |\\beta|\\right) m! \\ge m! \\ge 2^m\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。由 Weierstrass M 判别法，导数级数在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi mathvariant=\"double-struck\">T\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathbb T^2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 上一致绝对收敛，因此 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsubsup>\u003cmi>C\u003c/mi>\u003cmn>0\u003c/mn>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/msubsup>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">T\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">F \\in C_0^\\infty(\\mathbb T^2)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/li>\n\u003cli>\u003cstrong>不存在光滑零均值解\u003c/strong>：\n反设存在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>u\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsubsup>\u003cmi>C\u003c/mi>\u003cmn>0\u003c/mn>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/msubsup>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">T\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">u \\in C_0^\\infty(\\mathbb T^2)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 满足 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>N\u003c/mi>\u003cmi>α\u003c/mi>\u003c/msub>\u003cmi>u\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>F\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">N_\\alpha u = F\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\n两边取 Fourier 系数，对任意 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>k\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">k \\in \\mathbb Z^2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 均有：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>i\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>α\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmover accent=\"true\">\u003cmi>u\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmover accent=\"true\">\u003cmi>F\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2\\pi i (\\alpha k_1 + k_2) \\widehat{u}(k) = \\widehat{F}(k).\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n在选定的频率序列 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>k\u003c/mi>\u003cmo>=\u003c/mo>\u003cmsup>\u003cmi>k\u003c/mi>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>m\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">k = k^{(m)}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>（\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>m\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">m \\ge 2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>）上，计算解的 Fourier 系数模长：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmover accent=\"true\">\u003cmi>u\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmi>k\u003c/mi>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>m\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmover accent=\"true\">\u003cmi>F\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmi>k\u003c/mi>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>m\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>α\u003c/mi>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>m\u003c/mi>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>p\u003c/mi>\u003cmi>m\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003c/mfrac>\u003cmo>\u0026gt;\u003c/mo>\u003cmfrac>\u003cmsup>\u003cmn>10\u003c/mn>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmi>m\u003c/mi>\u003cmo>⋅\u003c/mo>\u003cmi>m\u003c/mi>\u003cmo stretchy=\"false\">!\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmo>⋅\u003c/mo>\u003cmfrac>\u003cmn>10\u003c/mn>\u003cmn>9\u003c/mn>\u003c/mfrac>\u003cmsup>\u003cmn>10\u003c/mn>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmi>m\u003c/mi>\u003cmo>⋅\u003c/mo>\u003cmi>m\u003c/mi>\u003cmo stretchy=\"false\">!\u003c/mo>\u003c/mrow>\u003c/msup>\u003c/mrow>\u003c/mfrac>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmn>9\u003c/mn>\u003cmrow>\u003cmn>20\u003c/mn>\u003cmi>π\u003c/mi>\u003c/mrow>\u003c/mfrac>\u003cmsup>\u003cmn>10\u003c/mn>\u003cmrow>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmi>m\u003c/mi>\u003cmo>⋅\u003c/mo>\u003cmi>m\u003c/mi>\u003cmo stretchy=\"false\">!\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|\\widehat{u}(k^{(m)})| = \\frac{|\\widehat{F}(k^{(m)})|}{2\\pi |\\alpha q_m - p_m|} \u0026gt; \\frac{10^{-\\frac{1}{2} m \\cdot m!}}{2\\pi \\cdot \\frac{10}{9} 10^{-m \\cdot m!}} = \\frac{9}{20\\pi} 10^{\\frac{1}{2} m \\cdot m!}.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n随着 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>m\u003c/mi>\u003cmo>→\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">m \\to \\infty\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmover accent=\"true\">\u003cmi>u\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmi>k\u003c/mi>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>m\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmfrac>\u003cmn>9\u003c/mn>\u003cmrow>\u003cmn>20\u003c/mn>\u003cmi>π\u003c/mi>\u003c/mrow>\u003c/mfrac>\u003cmsup>\u003cmn>10\u003c/mn>\u003cmrow>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmi>m\u003c/mi>\u003cmo>⋅\u003c/mo>\u003cmi>m\u003c/mi>\u003cmo stretchy=\"false\">!\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmo>→\u003c/mo>\u003cmo>+\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|\\widehat{u}(k^{(m)})| \\ge \\frac{9}{20\\pi} 10^{\\frac{1}{2} m \\cdot m!} \\to +\\infty.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n然而，任何连续函数 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>u\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsup>\u003cmi>C\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msup>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">T\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">u \\in C^0(\\mathbb T^2)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的 Fourier 系数必须一致有界：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmover accent=\"true\">\u003cmi>u\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>=\u003c/mo>\u003cmrow>\u003cmo fence=\"true\">∣\u003c/mo>\u003cmsub>\u003cmo>∫\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">T\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/msub>\u003cmi>u\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsup>\u003cmi>e\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>π\u003c/mi>\u003cmi>i\u003c/mi>\u003cmi>k\u003c/mi>\u003cmo>⋅\u003c/mo>\u003cmi>y\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmi>d\u003c/mi>\u003cmi>y\u003c/mi>\u003cmo fence=\"true\">∣\u003c/mo>\u003c/mrow>\u003cmo>≤\u003c/mo>\u003cmsub>\u003cmo>∫\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">T\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>u\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>d\u003c/mi>\u003cmi>y\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>u\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>C\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msup>\u003c/msub>\u003cmo>\u0026lt;\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|\\widehat{u}(k)| = \\left| \\int_{\\mathbb T^2} u(y) e^{-2\\pi i k \\cdot y} dy \\right| \\le \\int_{\\mathbb T^2} |u(y)| dy \\le \\|u\\|_{C^0} \u0026lt; \\infty.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n这与 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmover accent=\"true\">\u003cmi>u\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmi>k\u003c/mi>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>m\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>→\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|\\widehat{u}(k^{(m)})| \\to \\infty\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 发生直接矛盾！\n因此，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>N\u003c/mi>\u003cmi>α\u003c/mi>\u003c/msub>\u003cmi>u\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>F\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">N_\\alpha u = F\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 甚至没有任何连续解，更不可能存在光滑零均值解 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>u\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsubsup>\u003cmi>C\u003c/mi>\u003cmn>0\u003c/mn>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/msubsup>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">T\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">u \\in C_0^\\infty(\\mathbb T^2)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/li>\n\u003c/ol>\n","source":"assets/content/d0799a3e061fc7a6ebb1ae2309b6c02fb18c1ca40a6f420f2d2b9bed33b1ab76.html"});
